package yq

import (
	"fmt"
	"strconv"
	"strings"
)

// Kind mirrors the node classes of the YAML data model.
type Kind uint32

const (
	SequenceNode Kind = 1 << iota
	MappingNode
	ScalarNode
	AliasNode
)

func (k Kind) String() string {
	switch k {
	case SequenceNode:
		return "seq"
	case MappingNode:
		return "map"
	case ScalarNode:
		return "scalar"
	case AliasNode:
		return "alias"
	}
	return "unknown"
}

// Style is a bit set describing how a node was (or should be) presented.
type Style uint32

const (
	TaggedStyle Style = 1 << iota
	DoubleQuotedStyle
	SingleQuotedStyle
	LiteralStyle
	FoldedStyle
	FlowStyle
)

// Well known resolved tags.
const (
	TagStr   = "!!str"
	TagInt   = "!!int"
	TagFloat = "!!float"
	TagBool  = "!!bool"
	TagNull  = "!!null"
	TagMap   = "!!map"
	TagSeq   = "!!seq"
)

// CandidateNode is both the document node representation and the unit that
// flows through the expression pipeline.
type CandidateNode struct {
	Kind  Kind
	Style Style

	Tag    string
	Value  string
	Anchor string
	Alias  *CandidateNode

	Content []*CandidateNode

	HeadComment string
	LineComment string
	FootComment string

	Parent   *CandidateNode
	Key      *CandidateNode
	IsMapKey bool

	// Raw text captured before/after the document body (header comments,
	// separators) so that round trips keep their shape.
	LeadingContent  string
	TrailingContent string

	Document  uint
	Filename  string
	FileIndex int

	Line   int
	Column int

	// set when a node is created by the expression rather than parsed
	EvaluateTogether bool
}

func (n *CandidateNode) IsCollection() bool {
	return n.Kind == MappingNode || n.Kind == SequenceNode
}

// GetNiceTag returns the tag, resolving the "!!merge"/custom cases loosely.
func (n *CandidateNode) GetNiceTag() string {
	if n.Tag == "" {
		switch n.Kind {
		case MappingNode:
			return TagMap
		case SequenceNode:
			return TagSeq
		case AliasNode:
			return "!!alias"
		}
		return TagStr
	}
	return n.Tag
}

func (n *CandidateNode) guessTagFromValue() string {
	return guessScalarTag(n.Value)
}

// CreateChild produces an empty node that inherits document identity.
func (n *CandidateNode) CreateChild() *CandidateNode {
	return &CandidateNode{
		Parent:    n,
		Document:  n.Document,
		Filename:  n.Filename,
		FileIndex: n.FileIndex,
	}
}

// CreateReplacement builds a fresh node keeping this node's position in the
// tree (parent/key), which is what most operators want when returning a value.
func (n *CandidateNode) CreateReplacement(kind Kind, tag string, value string) *CandidateNode {
	node := &CandidateNode{
		Kind:      kind,
		Tag:       tag,
		Value:     value,
		Parent:    n.Parent,
		Key:       n.Key,
		Document:  n.Document,
		Filename:  n.Filename,
		FileIndex: n.FileIndex,
	}
	return node
}

func (n *CandidateNode) CreateReplacementWithComments(kind Kind, tag string, style Style) *CandidateNode {
	node := n.CreateReplacement(kind, tag, "")
	node.Style = style
	node.LeadingContent = n.LeadingContent
	node.TrailingContent = n.TrailingContent
	node.HeadComment = n.HeadComment
	node.LineComment = n.LineComment
	node.FootComment = n.FootComment
	return node
}

// Copy performs a deep clone including children.
func (n *CandidateNode) Copy() *CandidateNode {
	return n.doCopy(true)
}

// CopyWithoutContent clones scalar level information only.
func (n *CandidateNode) CopyWithoutContent() *CandidateNode {
	return n.doCopy(false)
}

func (n *CandidateNode) doCopy(deep bool) *CandidateNode {
	if n == nil {
		return nil
	}
	clone := &CandidateNode{
		Kind:            n.Kind,
		Style:           n.Style,
		Tag:             n.Tag,
		Value:           n.Value,
		Anchor:          n.Anchor,
		Alias:           n.Alias,
		HeadComment:     n.HeadComment,
		LineComment:     n.LineComment,
		FootComment:     n.FootComment,
		Parent:          n.Parent,
		IsMapKey:        n.IsMapKey,
		LeadingContent:  n.LeadingContent,
		TrailingContent: n.TrailingContent,
		Document:        n.Document,
		Filename:        n.Filename,
		FileIndex:       n.FileIndex,
		Line:            n.Line,
		Column:          n.Column,
	}
	if n.Key != nil {
		clone.Key = n.Key.Copy()
	}
	if deep {
		clone.Content = make([]*CandidateNode, len(n.Content))
		for i, child := range n.Content {
			cc := child.Copy()
			cc.Parent = clone
			clone.Content[i] = cc
		}
	}
	return clone
}

// SetChildrenParents fixes up parent pointers after structural surgery.
func (n *CandidateNode) SetChildrenParents() {
	for i, child := range n.Content {
		child.Parent = n
		if n.Kind == MappingNode {
			if i%2 == 1 {
				child.Key = n.Content[i-1]
			} else {
				child.IsMapKey = true
			}
		} else if n.Kind == SequenceNode {
			child.Key = &CandidateNode{Kind: ScalarNode, Tag: TagInt, Value: strconv.Itoa(i)}
		}
		child.SetChildrenParents()
	}
}

// AddKeyValueChild appends a key/value pair to a mapping node.
func (n *CandidateNode) AddKeyValueChild(key *CandidateNode, value *CandidateNode) {
	key.Parent = n
	key.IsMapKey = true
	value.Parent = n
	value.Key = key
	n.Content = append(n.Content, key, value)
}

// AddChild appends to a sequence node.
func (n *CandidateNode) AddChild(rhs *CandidateNode) {
	rhs.Parent = n
	rhs.Key = &CandidateNode{Kind: ScalarNode, Tag: TagInt, Value: strconv.Itoa(len(n.Content))}
	n.Content = append(n.Content, rhs)
}

// UpdateFrom copies the contents of other onto this node, in the manner used
// by the assignment operators.
func (n *CandidateNode) UpdateFrom(other *CandidateNode, prefs assignPreferences) {
	// only clobber the value/kind, keeping our position in the tree
	n.Content = make([]*CandidateNode, len(other.Content))
	for i, child := range other.Content {
		cc := child.Copy()
		cc.Parent = n
		n.Content[i] = cc
	}
	n.Kind = other.Kind
	n.Tag = other.Tag
	n.Value = other.Value
	n.Alias = other.Alias

	if !prefs.ClobberCustomTags || other.Tag != "" {
		n.Tag = other.Tag
	}

	n.UpdateAttributesFrom(other, prefs)
}

func (n *CandidateNode) UpdateAttributesFrom(other *CandidateNode, prefs assignPreferences) {
	if n.Kind != other.Kind {
		// changing kind invalidates the anchor
		n.Anchor = ""
	}
	n.Kind = other.Kind

	// don't clobber custom tags
	if !prefs.DontOverWriteAnchor {
		n.Anchor = other.Anchor
	}

	if other.Tag != "" && (!prefs.ClobberCustomTags || !strings.HasPrefix(n.Tag, "!!") || strings.HasPrefix(other.Tag, "!!")) {
		n.Tag = other.Tag
	}

	n.Style = other.Style

	if other.FootComment != "" {
		n.FootComment = other.FootComment
	}
	if other.HeadComment != "" {
		n.HeadComment = other.HeadComment
	}
	if other.LineComment != "" {
		n.LineComment = other.LineComment
	}
}

// GetPath walks up the parent chain producing the document path.
func (n *CandidateNode) GetPath() []interface{} {
	if n.Parent != nil && n.Key != nil {
		return append(n.Parent.GetPath(), n.Key.scalarValue())
	}
	return make([]interface{}, 0)
}

func (n *CandidateNode) scalarValue() interface{} {
	if n.Tag == TagInt {
		num, err := parseInt(n.Value)
		if err == nil {
			return int(num)
		}
	}
	return n.Value
}

// GetKeyNodeFor finds the value node in a mapping for the given key string.
func (n *CandidateNode) GetValueFor(key string) *CandidateNode {
	if n.Kind != MappingNode {
		return nil
	}
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == key {
			return n.Content[i+1]
		}
	}
	return nil
}

func (n *CandidateNode) String() string {
	return fmt.Sprintf("%v (%v)", n.Tag, n.Value)
}

// assignPreferences carries flags used when updating nodes in place.
type assignPreferences struct {
	DontOverWriteAnchor bool
	ClobberCustomTags   bool
	OnlyWriteNull       bool
	RHSIsExpression     bool
}

