package yq

import (
	"fmt"
	"strconv"
	"strings"
)

// yamlDecoder is a hand written YAML reader. It keeps enough presentation
// detail (styles, anchors, comments, raw header text) for yq to round trip
// documents without reformatting them.
type yamlDecoder struct {
	src     string
	off     int
	lineNo  int
	lineBeg int

	filename  string
	fileIndex int

	headerPreprocess bool

	pendingHead string
}

func newYamlDecoder(src string, filename string, fileIndex int, headerPreprocess bool) *yamlDecoder {
	return &yamlDecoder{
		src:              src,
		lineNo:           1,
		filename:         filename,
		fileIndex:        fileIndex,
		headerPreprocess: headerPreprocess,
	}
}

func (d *yamlDecoder) eof() bool { return d.off >= len(d.src) }

func (d *yamlDecoder) ch() byte {
	if d.off >= len(d.src) {
		return 0
	}
	return d.src[d.off]
}

func (d *yamlDecoder) at(i int) byte {
	if d.off+i >= len(d.src) || d.off+i < 0 {
		return 0
	}
	return d.src[d.off+i]
}

func (d *yamlDecoder) adv() {
	if d.off >= len(d.src) {
		return
	}
	if d.src[d.off] == '\n' {
		d.lineNo++
		d.lineBeg = d.off + 1
	}
	d.off++
}

// col is the zero based column of the cursor.
func (d *yamlDecoder) col() int { return d.off - d.lineBeg }

func (d *yamlDecoder) skipSpaces() {
	for d.ch() == ' ' || d.ch() == '\t' {
		d.adv()
	}
}

func (d *yamlDecoder) atEOL() bool { return d.eof() || d.ch() == '\n' }

func (d *yamlDecoder) toEOL() {
	for !d.atEOL() {
		d.adv()
	}
}

func (d *yamlDecoder) endLine() {
	d.toEOL()
	if d.ch() == '\n' {
		d.adv()
	}
}

// lineTextFrom returns the remainder of the line starting at off.
func (d *yamlDecoder) lineTextFrom(off int) string {
	end := strings.IndexByte(d.src[off:], '\n')
	if end < 0 {
		return d.src[off:]
	}
	return d.src[off : off+end]
}

func indentWidth(line string) int {
	n := 0
	for n < len(line) && line[n] == ' ' {
		n++
	}
	return n
}

func isBlankLine(line string) bool { return strings.TrimSpace(line) == "" }

func isCommentLine(line string) bool {
	t := strings.TrimLeft(line, " ")
	return strings.HasPrefix(t, "#")
}

func isDocStart(line string) bool {
	return line == "---" || strings.HasPrefix(line, "--- ") || strings.HasPrefix(line, "---\t")
}

func isDocEnd(line string) bool {
	return line == "..." || strings.HasPrefix(line, "... ")
}

// ---------------------------------------------------------------------------
// stream level
// ---------------------------------------------------------------------------

// Decode reads every document in the stream.
func (d *yamlDecoder) Decode() ([]*CandidateNode, error) {
	leading := ""
	if d.headerPreprocess {
		leading = d.slurpHeader()
	}

	docs := make([]*CandidateNode, 0)
	docIdx := uint(0)
	for {
		d.skipDocumentJunk()
		if d.eof() {
			break
		}
		node, err := d.parseDocument()
		if err != nil {
			return nil, err
		}
		if node == nil {
			continue
		}
		node.Document = docIdx
		node.Filename = d.filename
		node.FileIndex = d.fileIndex
		setDocumentOn(node, docIdx, d.filename, d.fileIndex)
		docs = append(docs, node)
		docIdx++
	}

	if len(docs) > 0 {
		docs[0].LeadingContent = leading
	} else if leading != "" {
		empty := &CandidateNode{Kind: ScalarNode, Tag: TagNull, Value: "", LeadingContent: leading,
			Filename: d.filename, FileIndex: d.fileIndex}
		docs = append(docs, empty)
	}
	return docs, nil
}

func setDocumentOn(n *CandidateNode, doc uint, filename string, fileIndex int) {
	n.Document = doc
	n.Filename = filename
	n.FileIndex = fileIndex
	if n.Key != nil {
		setDocumentOn(n.Key, doc, filename, fileIndex)
	}
	for _, c := range n.Content {
		setDocumentOn(c, doc, filename, fileIndex)
	}
}

// slurpHeader consumes the leading comment/directive/separator block so that it
// can be reproduced verbatim on output.
func (d *yamlDecoder) slurpHeader() string {
	start := d.off
	lastGood := d.off
	sawSeparator := false
	for !d.eof() {
		line := d.lineTextFrom(d.off)
		switch {
		case isBlankLine(line), isCommentLine(line), strings.HasPrefix(line, "%"):
			d.endLine()
		case isDocStart(line):
			if sawSeparator {
				return d.src[start:lastGood]
			}
			sawSeparator = true
			if line != "---" {
				// content follows the separator on the same line
				return d.src[start:d.off] + "---\n"
			}
			d.endLine()
			lastGood = d.off
			return d.src[start:lastGood]
		default:
			return d.src[start:lastGood]
		}
		if !sawSeparator {
			lastGood = d.off
		}
	}
	return d.src[start:lastGood]
}

// skipDocumentJunk moves past blank lines and end-of-document markers.
func (d *yamlDecoder) skipDocumentJunk() {
	for !d.eof() {
		line := d.lineTextFrom(d.off)
		if isBlankLine(line) || isDocEnd(line) || strings.HasPrefix(line, "%") {
			d.endLine()
			continue
		}
		return
	}
}

func (d *yamlDecoder) parseDocument() (*CandidateNode, error) {
	d.pendingHead = ""
	line := d.lineTextFrom(d.off)
	if isDocStart(line) {
		if line == "---" {
			d.endLine()
		} else {
			// "--- value" – jump the cursor past the marker
			d.adv()
			d.adv()
			d.adv()
			d.skipSpaces()
			node, err := d.parseBlockNode(d.col())
			if err != nil {
				return nil, err
			}
			d.finishDocument()
			return node, nil
		}
	}

	foot := d.readGap(0)
	_ = foot
	if d.eof() || d.atDocBoundary() {
		if d.pendingHead != "" {
			n := &CandidateNode{Kind: ScalarNode, Tag: TagNull, HeadComment: d.pendingHead, Line: d.lineNo}
			d.pendingHead = ""
			return n, nil
		}
		return nil, nil
	}

	d.skipSpaces()
	node, err := d.parseBlockNode(d.col())
	if err != nil {
		return nil, err
	}
	d.finishDocument()
	return node, nil
}

func (d *yamlDecoder) finishDocument() {
	// swallow trailing junk up to the next document
	for !d.eof() {
		line := d.lineTextFrom(d.off)
		if isDocStart(line) {
			return
		}
		if isDocEnd(line) || isBlankLine(line) {
			d.endLine()
			continue
		}
		return
	}
}

func (d *yamlDecoder) atDocBoundary() bool {
	if d.eof() {
		return true
	}
	line := d.lineTextFrom(d.lineBeg)
	return isDocStart(line) || isDocEnd(line)
}

// ---------------------------------------------------------------------------
// comment gaps
// ---------------------------------------------------------------------------

// readGap consumes blank and comment lines. The comment block sitting directly
// underneath the previous entry becomes that entry's foot comment when it is
// separated from what follows; everything else is queued as the head comment
// for the upcoming node.
func (d *yamlDecoder) readGap(blockIndent int) string {
	type grp struct{ text string }
	groups := make([]grp, 0)
	firstIsComment := false
	blankAfterFirstGroup := false
	first := true
	inGroup := false

	for !d.eof() {
		line := d.lineTextFrom(d.lineBeg + min(d.col(), len(line0(d, 0))))
		line = d.lineTextFrom(d.off)
		if isBlankLine(line) {
			if first {
				first = false
			}
			if len(groups) == 1 && inGroup {
				blankAfterFirstGroup = true
			}
			inGroup = false
			d.endLine()
			continue
		}
		if isCommentLine(line) {
			if first {
				firstIsComment = true
				first = false
			}
			text := commentText(line)
			if inGroup {
				groups[len(groups)-1].text += "\n" + text
			} else {
				groups = append(groups, grp{text: text})
				inGroup = true
			}
			d.endLine()
			continue
		}
		break
	}

	nextIndent := -1
	terminal := true
	if !d.eof() && !d.atDocBoundary() {
		line := d.lineTextFrom(d.off)
		nextIndent = indentWidth(line)
		terminal = nextIndent < blockIndent
	}

	foot := ""
	if firstIsComment && len(groups) > 0 {
		if blankAfterFirstGroup || len(groups) > 1 || terminal {
			foot = groups[0].text
			groups = groups[1:]
		}
	}

	texts := make([]string, 0, len(groups))
	for _, g := range groups {
		texts = append(texts, g.text)
	}
	head := strings.Join(texts, "\n\n")
	if head != "" {
		if d.pendingHead != "" {
			d.pendingHead += "\n\n" + head
		} else {
			d.pendingHead = head
		}
	}
	return foot
}

func line0(d *yamlDecoder, _ int) string { return d.lineTextFrom(d.lineBeg) }

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

// commentText strips the leading hash (and a single following space) from each
// comment line, matching how comments are stored on nodes.
func commentText(line string) string {
	t := strings.TrimLeft(line, " ")
	t = strings.TrimPrefix(t, "#")
	return strings.TrimRight(t, " \t\r")
}

func (d *yamlDecoder) takeHead() string {
	h := d.pendingHead
	d.pendingHead = ""
	return h
}

// readLineComment grabs a trailing "# ..." comment on the current line.
func (d *yamlDecoder) readLineComment() string {
	d.skipSpaces()
	if d.ch() == '#' {
		text := commentText(d.lineTextFrom(d.off))
		d.toEOL()
		return text
	}
	return ""
}

