package yq

import (
	"fmt"
	"strings"
)

// ---------------------------------------------------------------------------
// block level nodes
// ---------------------------------------------------------------------------

// parseBlockNode parses the node whose first character sits under the cursor.
// indent is the column that sibling entries of this node share.
func (d *yamlDecoder) parseBlockNode(indent int) (*CandidateNode, error) {
	head := d.takeHead()
	startLine := d.lineNo
	startCol := d.col()

	anchor, tag, err := d.parseProperties(indent)
	if err != nil {
		return nil, err
	}

	if anchor != "" || tag != "" {
		// properties may be followed by the value on a later line
		d.skipSpaces()
		if d.atEOL() || d.ch() == '#' {
			lineComment := d.readLineComment()
			d.endLine()
			foot := d.readGap(indent)
			_ = foot
			if d.eof() || d.atDocBoundary() {
				n := d.newScalar("", startLine, startCol)
				n.Anchor, n.HeadComment, n.LineComment = anchor, head, lineComment
				d.applyTag(n, tag)
				return n, nil
			}
			nextIndent := indentWidth(d.lineTextFrom(d.off))
			if nextIndent < indent || (nextIndent == indent && !d.lineStartsSeqItem()) {
				n := d.newScalar("", startLine, startCol)
				n.Anchor, n.HeadComment, n.LineComment = anchor, head, lineComment
				d.applyTag(n, tag)
				return n, nil
			}
			d.skipSpaces()
			inner, err := d.parseBlockNode(d.col())
			if err != nil {
				return nil, err
			}
			inner.Anchor = anchor
			if head != "" {
				inner.HeadComment = head
			}
			if lineComment != "" {
				inner.LineComment = lineComment
			}
			d.applyTag(inner, tag)
			return inner, nil
		}
	}

	node, err := d.parseBlockNodeContent(indent, startLine, startCol)
	if err != nil {
		return nil, err
	}
	if anchor != "" {
		node.Anchor = anchor
	}
	d.applyTag(node, tag)
	if head != "" && node.HeadComment == "" {
		node.HeadComment = head
	}
	return node, nil
}

func (d *yamlDecoder) applyTag(n *CandidateNode, tag string) {
	if tag == "" {
		return
	}
	n.Tag = tag
	if n.Kind == ScalarNode {
		if !strings.HasPrefix(tag, "!!") || (tag != TagStr && tag != TagInt && tag != TagFloat && tag != TagBool && tag != TagNull) {
			n.Style |= TaggedStyle
		} else {
			n.Style |= TaggedStyle
		}
	}
}

func (d *yamlDecoder) lineStartsSeqItem() bool {
	line := strings.TrimLeft(d.lineTextFrom(d.off), " ")
	return line == "-" || strings.HasPrefix(line, "- ") || strings.HasPrefix(line, "-\t")
}

func (d *yamlDecoder) parseBlockNodeContent(indent, startLine, startCol int) (*CandidateNode, error) {
	switch d.ch() {
	case '-':
		if d.at(1) == ' ' || d.at(1) == '\t' || d.at(1) == '\n' || d.at(1) == 0 {
			return d.parseBlockSeq(d.col())
		}
	case '?':
		if d.at(1) == ' ' || d.at(1) == '\n' || d.at(1) == 0 {
			return d.parseBlockMap(d.col(), nil)
		}
	case '[':
		return d.parseFlowNodeThenMaybeKey(indent)
	case '{':
		return d.parseFlowNodeThenMaybeKey(indent)
	case '|', '>':
		return d.parseBlockScalar(indent, startLine, startCol)
	case '*':
		alias, err := d.parseAlias(startLine, startCol)
		if err != nil {
			return nil, err
		}
		// an alias may be a mapping key: "*a: value"
		save := d.saveState()
		d.skipSpaces()
		if d.ch() == ':' && (d.at(1) == ' ' || d.at(1) == '\n' || d.at(1) == 0 || d.at(1) == '\t') {
			d.restoreState(save)
			return d.parseBlockMap(startCol, alias)
		}
		d.restoreState(save)
		return alias, nil
	}

	// Either a mapping whose first key starts here, or a plain/quoted scalar.
	key, ok, err := d.tryScanKey(indent)
	if err != nil {
		return nil, err
	}
	if ok {
		return d.parseBlockMap(startCol, key)
	}
	return d.parseBlockPlainOrQuoted(indent, startLine, startCol)
}

func (d *yamlDecoder) parseFlowNodeThenMaybeKey(indent int) (*CandidateNode, error) {
	startLine, startCol := d.lineNo, d.col()
	save := d.saveState()
	node, err := d.parseFlowNode()
	if err != nil {
		return nil, err
	}
	afterFlow := d.saveState()
	d.skipSpaces()
	if d.ch() == ':' && (d.at(1) == ' ' || d.at(1) == '\n' || d.at(1) == 0 || d.at(1) == '\t') {
		d.restoreState(save)
		key, ok, err := d.tryScanKey(indent)
		if err == nil && ok {
			return d.parseBlockMap(startCol, key)
		}
		d.restoreState(afterFlow)
	} else {
		d.restoreState(afterFlow)
	}
	node.Line, node.Column = startLine, startCol+1
	return node, nil
}

type decState struct {
	off, lineNo, lineBeg int
	pendingHead          string
}

func (d *yamlDecoder) saveState() decState {
	return decState{d.off, d.lineNo, d.lineBeg, d.pendingHead}
}

func (d *yamlDecoder) restoreState(s decState) {
	d.off, d.lineNo, d.lineBeg, d.pendingHead = s.off, s.lineNo, s.lineBeg, s.pendingHead
}

// parseProperties reads any anchor and tag decorations in either order.
func (d *yamlDecoder) parseProperties(indent int) (anchor string, tag string, err error) {
	for {
		d.skipSpaces()
		switch d.ch() {
		case '&':
			if anchor != "" {
				return anchor, tag, nil
			}
			d.adv()
			start := d.off
			for !d.atEOL() && !isFlowIndicator(d.ch()) && d.ch() != ' ' && d.ch() != '\t' {
				d.adv()
			}
			anchor = d.src[start:d.off]
		case '!':
			if tag != "" {
				return anchor, tag, nil
			}
			start := d.off
			d.adv()
			if d.ch() == '!' {
				d.adv()
			}
			for !d.atEOL() && d.ch() != ' ' && d.ch() != '\t' && !isFlowIndicator(d.ch()) {
				d.adv()
			}
			tag = d.src[start:d.off]
		default:
			return anchor, tag, nil
		}
	}
}

func isFlowIndicator(c byte) bool {
	switch c {
	case ',', '[', ']', '{', '}':
		return true
	}
	return false
}

func (d *yamlDecoder) newScalar(value string, line, col int) *CandidateNode {
	return &CandidateNode{
		Kind:      ScalarNode,
		Tag:       guessScalarTag(value),
		Value:     value,
		Line:      line,
		Column:    col + 1,
		Filename:  d.filename,
		FileIndex: d.fileIndex,
	}
}

func (d *yamlDecoder) parseAlias(line, col int) (*CandidateNode, error) {
	d.adv() // '*'
	start := d.off
	for !d.atEOL() && d.ch() != ' ' && d.ch() != '\t' && !isFlowIndicator(d.ch()) {
		d.adv()
	}
	return &CandidateNode{
		Kind:      AliasNode,
		Value:     d.src[start:d.off],
		Line:      line,
		Column:    col + 1,
		Filename:  d.filename,
		FileIndex: d.fileIndex,
	}, nil
}

// tryScanKey attempts to read a mapping key at the cursor. On failure the
// cursor is restored.
func (d *yamlDecoder) tryScanKey(indent int) (*CandidateNode, bool, error) {
	save := d.saveState()
	line, col := d.lineNo, d.col()

	if d.ch() == '?' && (d.at(1) == ' ' || d.at(1) == '\n' || d.at(1) == 0) {
		d.restoreState(save)
		return nil, false, nil
	}

	var key *CandidateNode
	switch d.ch() {
	case '"', '\'':
		v, style, err := d.parseQuoted(indent)
		if err != nil {
			d.restoreState(save)
			return nil, false, nil
		}
		key = d.newScalar(v, line, col)
		key.Tag = TagStr
		key.Style = style
	case '[', '{':
		n, err := d.parseFlowNode()
		if err != nil {
			d.restoreState(save)
			return nil, false, nil
		}
		key = n
		key.Line, key.Column = line, col+1
	case '&', '!', '*':
		d.restoreState(save)
		return nil, false, nil
	default:
		v, ok := d.scanPlainKey()
		if !ok {
			d.restoreState(save)
			return nil, false, nil
		}
		key = d.newScalar(v, line, col)
	}

	if d.ch() == ' ' || d.ch() == '\t' {
		d.skipSpaces()
	}
	if d.ch() != ':' {
		d.restoreState(save)
		return nil, false, nil
	}
	nxt := d.at(1)
	if nxt != ' ' && nxt != '\t' && nxt != '\n' && nxt != 0 {
		d.restoreState(save)
		return nil, false, nil
	}
	return key, true, nil
}

// scanPlainKey reads a plain scalar that is bounded by ": " on the same line.
func (d *yamlDecoder) scanPlainKey() (string, bool) {
	start := d.off
	for !d.atEOL() {
		c := d.ch()
		if c == ':' {
			nxt := d.at(1)
			if nxt == ' ' || nxt == '\t' || nxt == '\n' || nxt == 0 {
				break
			}
		}
		if c == '#' && d.off > start && (d.src[d.off-1] == ' ' || d.src[d.off-1] == '\t') {
			return "", false
		}
		d.adv()
	}
	if d.atEOL() {
		return "", false
	}
	raw := strings.TrimRight(d.src[start:d.off], " \t")
	if raw == "" {
		return "", false
	}
	return raw, true
}

// ---------------------------------------------------------------------------
// block sequences and mappings
// ---------------------------------------------------------------------------

func (d *yamlDecoder) parseBlockSeq(indent int) (*CandidateNode, error) {
	seq := &CandidateNode{
		Kind: SequenceNode, Tag: TagSeq,
		Line: d.lineNo, Column: indent + 1,
		Filename: d.filename, FileIndex: d.fileIndex,
	}
	seq.HeadComment = d.takeHead()

	for {
		itemHead := d.takeHead()
		d.adv() // '-'
		var item *CandidateNode
		var err error
		if d.atEOL() || d.ch() == '#' {
			lineComment := d.readLineComment()
			d.endLine()
			foot := d.readGap(indent)
			_ = foot
			item = d.childOrNull(indent)
			if item == nil {
				item = d.newScalar("", d.lineNo, indent)
			}
			if lineComment != "" && item.LineComment == "" {
				item.LineComment = lineComment
			}
		} else {
			d.skipSpaces()
			item, err = d.parseBlockNode(d.col())
			if err != nil {
				return nil, err
			}
			if item.LineComment == "" && !d.atEOL() {
				item.LineComment = d.readLineComment()
			}
			d.endLine()
		}
		if itemHead != "" && item.HeadComment == "" {
			item.HeadComment = itemHead
		}
		seq.AddChild(item)

		foot := d.readGap(indent)
		if foot != "" {
			item.FootComment = foot
		}
		if d.eof() || d.atDocBoundary() {
			break
		}
		nextIndent := indentWidth(d.lineTextFrom(d.off))
		if nextIndent != indent || !d.lineStartsSeqItem() {
			break
		}
		d.skipSpaces()
	}
	return seq, nil
}

// childOrNull parses the block child of an entry whose value lives on the
// following lines, or reports nil when there is no such child.
func (d *yamlDecoder) childOrNull(indent int) *CandidateNode {
	if d.eof() || d.atDocBoundary() {
		return nil
	}
	nextIndent := indentWidth(d.lineTextFrom(d.off))
	if nextIndent > indent {
		d.skipSpaces()
		child, err := d.parseBlockNode(d.col())
		if err != nil {
			return nil
		}
		return child
	}
	if nextIndent == indent && d.lineStartsSeqItem() {
		d.skipSpaces()
		child, err := d.parseBlockSeq(indent)
		if err != nil {
			return nil
		}
		return child
	}
	return nil
}

func (d *yamlDecoder) parseBlockMap(indent int, firstKey *CandidateNode) (*CandidateNode, error) {
	m := &CandidateNode{
		Kind: MappingNode, Tag: TagMap,
		Line: d.lineNo, Column: indent + 1,
		Filename: d.filename, FileIndex: d.fileIndex,
	}
	m.HeadComment = d.takeHead()

	key := firstKey
	for {
		keyHead := d.takeHead()
		if key == nil {
			if d.ch() == '?' {
				k, err := d.parseExplicitKey(indent)
				if err != nil {
					return nil, err
				}
				key = k
			} else {
				k, ok, err := d.tryScanKey(indent)
				if err != nil {
					return nil, err
				}
				if !ok {
					return nil, fmt.Errorf("yaml: line %v: could not find expected ':'", d.lineNo)
				}
				key = k
			}
		}
		if keyHead != "" && key.HeadComment == "" {
			key.HeadComment = keyHead
		}

		// consume the ':'
		d.skipSpaces()
		if d.ch() == ':' {
			d.adv()
		}

		var value *CandidateNode
		d.skipSpaces()
		if d.atEOL() || d.ch() == '#' {
			keyLineComment := d.readLineComment()
			d.endLine()
			foot := d.readGap(indent)
			pendingFoot := foot
			value = d.childOrNull(indent)
			if value == nil {
				value = d.newScalar("", d.lineNo, indent)
				if pendingFoot != "" {
					key.FootComment = pendingFoot
				}
			} else if pendingFoot != "" {
				key.HeadComment = joinComments(key.HeadComment, pendingFoot)
			}
			if keyLineComment != "" {
				key.LineComment = keyLineComment
			}
		} else {
			var err error
			value, err = d.parseBlockNode(indent)
			if err != nil {
				return nil, err
			}
			if !d.atEOL() {
				if lc := d.readLineComment(); lc != "" && value.LineComment == "" {
					value.LineComment = lc
				}
			}
			d.endLine()
		}

		m.AddKeyValueChild(key, value)
		key = nil

		foot := d.readGap(indent)
		if foot != "" {
			last := m.Content[len(m.Content)-2]
			last.FootComment = joinComments(last.FootComment, foot)
		}

		if d.eof() || d.atDocBoundary() {
			break
		}
		nextIndent := indentWidth(d.lineTextFrom(d.off))
		if nextIndent != indent {
			break
		}
		if d.lineStartsSeqItem() {
			break
		}
		d.skipSpaces()
	}
	return m, nil
}

func joinComments(a, b string) string {
	if a == "" {
		return b
	}
	if b == "" {
		return a
	}
	return a + "\n" + b
}

func (d *yamlDecoder) parseExplicitKey(indent int) (*CandidateNode, error) {
	d.adv() // '?'
	d.skipSpaces()
	if d.atEOL() {
		d.endLine()
		d.readGap(indent)
		k := d.childOrNull(indent)
		if k == nil {
			k = d.newScalar("", d.lineNo, indent)
		}
		return k, nil
	}
	k, err := d.parseBlockNode(d.col())
	if err != nil {
		return nil, err
	}
	d.endLine()
	d.readGap(indent)
	return k, nil
}

