// ---------------------------------------------------------------------------

// parseBlockNode parses the node whose first character sits under the cursor.
// indent is the column that sibling entries of this node share.
func (d *yamlDecoder) parseBlockNode(indent int) (*CandidateNode, error) {
	head := d.takeHead()
	startLine := d.lineNo
	startCol := d.col()

	anchor, tag, err := d.parseProperties(indent)
	if err != nil {
		return nil, err
	}

	if anchor != "" || tag != "" {
		// properties may be followed by the value on a later line
		d.skipSpaces()
		if d.atEOL() || d.ch() == '#' {
			lineComment := d.readLineComment()
			d.endLine()
			foot := d.readGap(indent)
			_ = foot
			if d.eof() || d.atDocBoundary() {
				n := d.newScalar("", startLine, startCol)
				n.Anchor, n.HeadComment, n.LineComment = anchor, head, lineComment
				d.applyTag(n, tag)
				return n, nil
			}
			nextIndent := indentWidth(d.lineTextFrom(d.off))
			if nextIndent < indent || (nextIndent == indent && !d.lineStartsSeqItem()) {
				n := d.newScalar("", startLine, startCol)
				n.Anchor, n.HeadComment, n.LineComment = anchor, head, lineComment
				d.applyTag(n, tag)
				return n, nil
			}
			d.skipSpaces()
			inner, err := d.parseBlockNode(d.col())
			if err != nil {
				return nil, err
			}
			inner.Anchor = anchor
			if head != "" {
				inner.HeadComment = head
			}
			if lineComment != "" {
				inner.LineComment = lineComment
			}
			d.applyTag(inner, tag)
			return inner, nil
		}
	}

	node, err := d.parseBlockNodeContent(indent, startLine, startCol)
	if err != nil {
		return nil, err
	}
	if anchor != "" {
		node.Anchor = anchor
	}
	d.applyTag(node, tag)
	if head != "" && node.HeadComment == "" {
		node.HeadComment = head
	}
	return node, nil
}

func (d *yamlDecoder) applyTag(n *CandidateNode, tag string) {
	if tag == "" {
		return
	}
	n.Tag = tag
	if n.Kind == ScalarNode {
