package yq

import (
	"fmt"
	"strconv"
	"strings"
)

// ---------------------------------------------------------------------------
// scalars
// ---------------------------------------------------------------------------

func (d *yamlDecoder) parseBlockPlainOrQuoted(indent, startLine, startCol int) (*CandidateNode, error) {
	if d.ch() == '"' || d.ch() == '\'' {
		v, style, err := d.parseQuoted(indent)
		if err != nil {
			return nil, err
		}
		n := d.newScalar(v, startLine, startCol)
		n.Tag = TagStr
		n.Style = style
		return n, nil
	}
	v, err := d.parsePlainMultiline(indent)
	if err != nil {
		return nil, err
	}
	return d.newScalar(v, startLine, startCol), nil
}

// parsePlainMultiline reads a plain scalar, following its continuation lines.
func (d *yamlDecoder) parsePlainMultiline(indent int) (string, error) {
	parts := []string{d.readPlainLine()}
	breaks := []int{}

	for {
		save := d.saveState()
		if !d.atEOL() {
			break
		}
		d.endLine()
		blanks := 0
		for !d.eof() && isBlankLine(d.lineTextFrom(d.off)) {
			blanks++
			d.endLine()
		}
		if d.eof() || d.atDocBoundary() {
			d.restoreState(save)
			break
		}
		line := d.lineTextFrom(d.off)
		if indentWidth(line) <= indent || isCommentLine(line) {
			d.restoreState(save)
			break
		}
		d.skipSpaces()
		if d.lineStartsSeqItem() {
			d.restoreState(save)
			break
		}
		if _, ok, _ := d.tryScanKey(indent); ok {
			d.restoreState(save)
			break
		}
		text := d.readPlainLine()
		if text == "" {
			d.restoreState(save)
			break
		}
		breaks = append(breaks, blanks)
		parts = append(parts, text)
	}

	var sb strings.Builder
	sb.WriteString(parts[0])
	for i := 1; i < len(parts); i++ {
		if breaks[i-1] == 0 {
			sb.WriteString(" ")
		} else {
			sb.WriteString(strings.Repeat("\n", breaks[i-1]))
		}
		sb.WriteString(parts[i])
	}
	return sb.String(), nil
}

// readPlainLine consumes the plain scalar text on the current line.
func (d *yamlDecoder) readPlainLine() string {
	start := d.off
	for !d.atEOL() {
		c := d.ch()
		if c == '#' && d.off > start && (d.src[d.off-1] == ' ' || d.src[d.off-1] == '\t') {
			break
		}
		if c == ':' {
			nxt := d.at(1)
			if nxt == ' ' || nxt == '\t' || nxt == '\n' || nxt == 0 {
				break
			}
		}
		d.adv()
	}
	return strings.TrimRight(d.src[start:d.off], " \t")
}

func (d *yamlDecoder) parseQuoted(indent int) (string, Style, error) {
	quote := d.ch()
	d.adv()
	var sb strings.Builder
	style := SingleQuotedStyle
	if quote == '"' {
		style = DoubleQuotedStyle
	}

	pendingBreaks := 0
	sawContentOnLine := true

	flushBreaks := func() {
		if pendingBreaks == 1 {
			sb.WriteString(" ")
		} else if pendingBreaks > 1 {
			sb.WriteString(strings.Repeat("\n", pendingBreaks-1))
		}
		pendingBreaks = 0
	}

	for {
		if d.eof() {
			return "", style, fmt.Errorf("yaml: found unexpected end of stream")
		}
		c := d.ch()
		if c == '\n' {
			d.adv()
			pendingBreaks++
			// skip the indentation of the continuation line
			for d.ch() == ' ' || d.ch() == '\t' {
				d.adv()
			}
			sawContentOnLine = false
			continue
		}
		if !sawContentOnLine {
			flushBreaks()
			sawContentOnLine = true
		}
		if quote == '\'' {
			if c == '\'' {
				if d.at(1) == '\'' {
					sb.WriteByte('\'')
					d.adv()
					d.adv()
					continue
				}
				d.adv()
				break
			}
			sb.WriteByte(c)
			d.adv()
			continue
		}
		// double quoted
		if c == '"' {
			d.adv()
			break
		}
		if c == '\\' {
			d.adv()
			if d.ch() == '\n' {
				// escaped line break swallows the fold
				d.adv()
				for d.ch() == ' ' || d.ch() == '\t' {
					d.adv()
				}
				sawContentOnLine = true
				continue
			}
			esc, err := d.readEscape()
			if err != nil {
				return "", style, err
			}
			sb.WriteString(esc)
			continue
		}
		sb.WriteByte(c)
		d.adv()
	}
	return sb.String(), style, nil
}

func (d *yamlDecoder) readEscape() (string, error) {
	c := d.ch()
	d.adv()
	switch c {
	case '0':
		return "\x00", nil
	case 'a':
		return "\a", nil
	case 'b':
		return "\b", nil
	case 't', '\t':
		return "\t", nil
	case 'n':
		return "\n", nil
	case 'v':
		return "\v", nil
	case 'f':
		return "\f", nil
	case 'r':
		return "\r", nil
	case 'e':
		return "\x1b", nil
	case ' ':
		return " ", nil
	case '"':
		return "\"", nil
	case '/':
		return "/", nil
	case '\\':
		return "\\", nil
	case 'N':
		return "", nil
	case '_':
		return " ", nil
	case 'L':
		return " ", nil
	case 'P':
		return " ", nil
	case 'x':
		return d.readHexEscape(2)
	case 'u':
		return d.readHexEscape(4)
	case 'U':
		return d.readHexEscape(8)
	}
	return "", fmt.Errorf("yaml: found unknown escape character %q", string(c))
}

func (d *yamlDecoder) readHexEscape(n int) (string, error) {
	if d.off+n > len(d.src) {
		return "", fmt.Errorf("yaml: invalid escape sequence")
	}
	digits := d.src[d.off : d.off+n]
	v, err := strconv.ParseUint(digits, 16, 32)
	if err != nil {
		return "", fmt.Errorf("yaml: invalid escape sequence")
	}
	for i := 0; i < n; i++ {
		d.adv()
	}
	if n == 2 {
		return string(rune(v)), nil
	}
	return string(rune(v)), nil
}

// parseBlockScalar handles the literal (|) and folded (>) styles.
func (d *yamlDecoder) parseBlockScalar(indent, startLine, startCol int) (*CandidateNode, error) {
	folded := d.ch() == '>'
	d.adv()

	explicitIndent := 0
	chomp := byte(0)
	for {
		c := d.ch()
		if c >= '1' && c <= '9' {
			explicitIndent = int(c - '0')
			d.adv()
			continue
		}
		if c == '+' || c == '-' {
			chomp = c
			d.adv()
			continue
		}
		break
	}
	lineComment := d.readLineComment()
	d.endLine()

	contentIndent := 0
	if explicitIndent > 0 {
		contentIndent = indent + explicitIndent
	}

	type blkLine struct {
		text  string
		blank bool
	}
	lines := make([]blkLine, 0)

	for !d.eof() {
		lineStart := d.off
		line := d.lineTextFrom(lineStart)
		if isBlankLine(line) {
			lines = append(lines, blkLine{blank: true})
			d.endLine()
			continue
		}
		ind := indentWidth(line)
		if contentIndent == 0 {
			if ind <= indent {
				break
			}
			contentIndent = ind
		}
		if ind < contentIndent {
			break
		}
		text := line
		if len(text) >= contentIndent {
			text = text[contentIndent:]
		}
		lines = append(lines, blkLine{text: text})
		d.endLine()
	}

	// drop trailing blank lines beyond what chomping keeps
	trailing := 0
	for len(lines) > 0 && lines[len(lines)-1].blank {
		trailing++
		lines = lines[:len(lines)-1]
	}

	var sb strings.Builder
	if folded {
		prevMoreIndented := false
		for i, l := range lines {
			if l.blank {
				sb.WriteString("\n")
				prevMoreIndented = false
				continue
			}
			moreIndented := strings.HasPrefix(l.text, " ") || strings.HasPrefix(l.text, "\t")
			if i > 0 {
				prev := lines[i-1]
				if !prev.blank {
					if moreIndented || prevMoreIndented {
						sb.WriteString("\n")
					} else {
						sb.WriteString(" ")
					}
				}
			}
			sb.WriteString(l.text)
			prevMoreIndented = moreIndented
		}
	} else {
		for i, l := range lines {
			if i > 0 {
				sb.WriteString("\n")
			}
			if !l.blank {
				sb.WriteString(l.text)
			}
		}
	}

	value := sb.String()
	switch chomp {
	case '-':
		// strip: no trailing newline
	case '+':
		if len(lines) > 0 || trailing > 0 {
			value += "\n" + strings.Repeat("\n", trailing)
		}
	default:
		if len(lines) > 0 {
			value += "\n"
		}
	}

	n := &CandidateNode{
		Kind: ScalarNode, Tag: TagStr, Value: value,
		Line: startLine, Column: startCol + 1,
		LineComment: lineComment,
		Filename:    d.filename, FileIndex: d.fileIndex,
	}
	if folded {
		n.Style = FoldedStyle
	} else {
		n.Style = LiteralStyle
	}
	if chomp == '-' {
		n.blockChomp = "-"
	} else if chomp == '+' {
		n.blockChomp = "+"
	}
	if explicitIndent > 0 {
		n.blockIndent = explicitIndent
	}
	return n, nil
}

// ---------------------------------------------------------------------------
// flow collections
// ---------------------------------------------------------------------------

func (d *yamlDecoder) skipFlowSpace() {
	for {
		if d.ch() == ' ' || d.ch() == '\t' || d.ch() == '\n' {
			d.adv()
			continue
		}
		if d.ch() == '#' {
			d.toEOL()
			continue
		}
		return
	}
}

func (d *yamlDecoder) parseFlowNode() (*CandidateNode, error) {
	d.skipFlowSpace()
	line, col := d.lineNo, d.col()
	anchor, tag, err := d.parseProperties(0)
	if err != nil {
		return nil, err
	}
	d.skipFlowSpace()

	var node *CandidateNode
	switch d.ch() {
	case '[':
		node, err = d.parseFlowSeq()
	case '{':
		node, err = d.parseFlowMap()
	case '*':
		node, err = d.parseAlias(line, col)
	case '"', '\'':
		v, style, qerr := d.parseQuoted(0)
		if qerr != nil {
			return nil, qerr
		}
		node = d.newScalar(v, line, col)
		node.Tag = TagStr
		node.Style = style
	default:
		v := d.readFlowPlain()
		node = d.newScalar(v, line, col)
	}
	if err != nil {
		return nil, err
	}
	node.Line, node.Column = line, col+1
	if anchor != "" {
		node.Anchor = anchor
	}
	d.applyTag(node, tag)
	return node, nil
}

func (d *yamlDecoder) readFlowPlain() string {
	var sb strings.Builder
	pendingSpace := false
	for {
		if d.eof() {
			break
		}
		c := d.ch()
		if c == '\n' {
			d.adv()
			d.skipSpaces()
			pendingSpace = true
			continue
		}
		if isFlowIndicator(c) {
			break
		}
		if c == ':' {
			nxt := d.at(1)
			if nxt == ' ' || nxt == '\t' || nxt == '\n' || nxt == 0 || isFlowIndicator(nxt) {
				break
			}
		}
		if c == '#' && sb.Len() > 0 && (d.src[d.off-1] == ' ' || d.src[d.off-1] == '\t') {
			break
		}
		if pendingSpace {
			sb.WriteString(" ")
			pendingSpace = false
		}
		sb.WriteByte(c)
		d.adv()
	}
	return strings.TrimRight(sb.String(), " \t")
}

func (d *yamlDecoder) parseFlowSeq() (*CandidateNode, error) {
	line, col := d.lineNo, d.col()
	d.adv() // '['
	seq := &CandidateNode{Kind: SequenceNode, Tag: TagSeq, Style: FlowStyle,
		Line: line, Column: col + 1, Filename: d.filename, FileIndex: d.fileIndex}
	for {
		d.skipFlowSpace()
		if d.eof() {
			return nil, fmt.Errorf("yaml: line %v: did not find expected ',' or ']'", d.lineNo)
		}
		if d.ch() == ']' {
			d.adv()
			break
		}
		item, err := d.parseFlowNode()
		if err != nil {
			return nil, err
		}
		d.skipFlowSpace()
		// a lone "key: value" inside [] denotes a single pair mapping
		if d.ch() == ':' && (d.at(1) == ' ' || d.at(1) == '\n' || isFlowIndicator(d.at(1)) || d.at(1) == 0) {
			d.adv()
			d.skipFlowSpace()
			var value *CandidateNode
			if d.ch() == ',' || d.ch() == ']' {
				value = d.newScalar("", d.lineNo, d.col())
			} else {
				value, err = d.parseFlowNode()
				if err != nil {
					return nil, err
				}
			}
			pair := &CandidateNode{Kind: MappingNode, Tag: TagMap, Style: FlowStyle,
				Line: item.Line, Column: item.Column, Filename: d.filename, FileIndex: d.fileIndex}
			pair.AddKeyValueChild(item, value)
			item = pair
			d.skipFlowSpace()
		}
		seq.AddChild(item)
		if d.ch() == ',' {
			d.adv()
			continue
		}
		if d.ch() == ']' {
			d.adv()
			break
		}
		if d.eof() {
			return nil, fmt.Errorf("yaml: line %v: did not find expected ',' or ']'", d.lineNo)
		}
		return nil, fmt.Errorf("yaml: line %v: did not find expected ',' or ']'", d.lineNo)
	}
	return seq, nil
}

func (d *yamlDecoder) parseFlowMap() (*CandidateNode, error) {
	line, col := d.lineNo, d.col()
	d.adv() // '{'
	m := &CandidateNode{Kind: MappingNode, Tag: TagMap, Style: FlowStyle,
		Line: line, Column: col + 1, Filename: d.filename, FileIndex: d.fileIndex}
	for {
		d.skipFlowSpace()
		if d.eof() {
			return nil, fmt.Errorf("yaml: line %v: did not find expected ',' or '}'", d.lineNo)
		}
		if d.ch() == '}' {
			d.adv()
			break
		}
		explicit := false
		if d.ch() == '?' && (d.at(1) == ' ' || d.at(1) == '\n') {
			d.adv()
			explicit = true
		}
		key, err := d.parseFlowNode()
		if err != nil {
			return nil, err
		}
		_ = explicit
		d.skipFlowSpace()
		var value *CandidateNode
		if d.ch() == ':' {
			d.adv()
			d.skipFlowSpace()
			if d.ch() == ',' || d.ch() == '}' {
				value = d.newScalar("", d.lineNo, d.col())
			} else {
				value, err = d.parseFlowNode()
				if err != nil {
					return nil, err
				}
			}
		} else {
			value = d.newScalar("", d.lineNo, d.col())
			value.Tag = TagNull
		}
		m.AddKeyValueChild(key, value)
		d.skipFlowSpace()
		if d.ch() == ',' {
			d.adv()
			continue
		}
		if d.ch() == '}' {
			d.adv()
			break
		}
		return nil, fmt.Errorf("yaml: line %v: did not find expected ',' or '}'", d.lineNo)
	}
	return m, nil
}

