package yq

import (
	"fmt"
	"io"
	"strings"
	"unicode/utf8"
)

// yamlEncoder renders nodes back to YAML text.
type yamlEncoder struct {
	indentWidth        int
	compactSeq         bool
	unwrapScalar       bool
	printDocSeparators bool
	colorise           bool
	docsWritten        int
}

func newYamlEncoder(prefs *EncoderPrefs) Encoder {
	indent := prefs.Indent
	if indent < 1 {
		indent = 4
	}
	return &yamlEncoder{
		indentWidth:        indent,
		compactSeq:         prefs.CompactSeqIndent,
		unwrapScalar:       prefs.UnwrapScalar,
		printDocSeparators: prefs.PrintDocSeparators,
		colorise:           prefs.Colorise,
	}
}

func (e *yamlEncoder) CanHandleAliases() bool { return true }

func (e *yamlEncoder) PrintDocumentSeparator(w io.Writer) error { return nil }

func (e *yamlEncoder) PrintLeadingContent(w io.Writer, content string) error { return nil }

func (e *yamlEncoder) Encode(w io.Writer, node *CandidateNode) error {
	leading := node.LeadingContent
	if !e.printDocSeparators {
		leading = stripSeparators(leading)
	}
	if e.docsWritten > 0 && e.printDocSeparators && !hasSeparator(leading) {
		if _, err := io.WriteString(w, "---\n"); err != nil {
			return err
		}
	}
	if leading != "" {
		if _, err := io.WriteString(w, leading); err != nil {
			return err
		}
	}
	e.docsWritten++

	// an unwrapped top level scalar prints its raw value
	if node.Kind == ScalarNode && e.unwrapScalar && node.Style&(LiteralStyle|FoldedStyle) == 0 {
		_, err := io.WriteString(w, node.Value+"\n")
		return err
	}

	var sb strings.Builder
	e.writeTopLevel(&sb, node)
	_, err := io.WriteString(w, sb.String())
	return err
}

func hasSeparator(leading string) bool {
	for _, line := range strings.Split(leading, "\n") {
		if isDocStart(line) {
			return true
		}
	}
	return false
}

func stripSeparators(leading string) string {
	if leading == "" {
		return ""
	}
	lines := strings.Split(leading, "\n")
	out := make([]string, 0, len(lines))
	for _, line := range lines {
		if isDocStart(line) {
			continue
		}
		out = append(out, line)
	}
	return strings.Join(out, "\n")
}

func (e *yamlEncoder) writeTopLevel(sb *strings.Builder, node *CandidateNode) {
	e.writeComment(sb, node.HeadComment, 0)
	switch {
	case node.Kind == MappingNode && node.Style&FlowStyle == 0 && len(node.Content) > 0:
		e.writeMapBody(sb, node, 0)
	case node.Kind == SequenceNode && node.Style&FlowStyle == 0 && len(node.Content) > 0:
		e.writeSeqBody(sb, node, 0)
	default:
		sb.WriteString(e.inlineValue(node, 0))
		if node.LineComment != "" {
			sb.WriteString(" " + e.colorComment("#"+node.LineComment))
		}
		sb.WriteString("\n")
	}
	e.writeComment(sb, node.FootComment, 0)
}

func (e *yamlEncoder) writeComment(sb *strings.Builder, comment string, indent int) {
	if comment == "" {
		return
	}
	pad := strings.Repeat(" ", indent)
	for _, line := range strings.Split(strings.TrimRight(comment, "\n"), "\n") {
		if line == "" {
			sb.WriteString("\n")
			continue
		}
		sb.WriteString(pad + e.colorComment("#"+line) + "\n")
	}
}

func (e *yamlEncoder) writeMapBody(sb *strings.Builder, node *CandidateNode, indent int) {
	pad := strings.Repeat(" ", indent)
	for i := 0; i+1 < len(node.Content); i += 2 {
		key := node.Content[i]
		value := node.Content[i+1]
		e.writeComment(sb, key.HeadComment, indent)
		if value.Kind == ScalarNode && value.HeadComment != "" && key.HeadComment == "" {
			// scalar values sit on the key line, so their head comment is
			// pushed out after the entry (see writeAfter)
		}
		sb.WriteString(pad)
		if key.Kind == ScalarNode {
			sb.WriteString(e.scalarText(key, indent, true))
		} else {
			sb.WriteString("? ")
			sb.WriteString(e.inlineValue(key, indent))
			sb.WriteString("\n" + pad)
		}
		sb.WriteString(e.colorPunct(":"))
		if key.LineComment != "" {
			sb.WriteString(" " + e.colorComment("#"+key.LineComment))
		}
		e.writeValue(sb, value, indent)
		e.writeComment(sb, key.FootComment, indent)
	}
}

// writeValue emits the part of an entry that follows the ":" or "-".
func (e *yamlEncoder) writeValue(sb *strings.Builder, value *CandidateNode, indent int) {
	child := indent + e.indentWidth
	switch {
	case value.Kind == MappingNode && value.Style&FlowStyle == 0 && len(value.Content) > 0:
		sb.WriteString("\n")
		e.writeMapBody(sb, value, child)
	case value.Kind == SequenceNode && value.Style&FlowStyle == 0 && len(value.Content) > 0:
		sb.WriteString("\n")
		seqIndent := child
		if e.compactSeq {
			seqIndent = indent
		}
		e.writeSeqBody(sb, value, seqIndent)
	default:
		text := e.inlineValue(value, indent)
		if text != "" {
			sb.WriteString(" " + text)
		}
		if value.LineComment != "" {
			sb.WriteString(" " + e.colorComment("#"+value.LineComment))
		}
		sb.WriteString("\n")
		e.writeComment(sb, value.HeadComment, indent)
		e.writeComment(sb, value.FootComment, indent)
	}
}

func (e *yamlEncoder) writeSeqBody(sb *strings.Builder, node *CandidateNode, indent int) {
	pad := strings.Repeat(" ", indent)
	for _, item := range node.Content {
		e.writeComment(sb, item.HeadComment, indent)
		sb.WriteString(pad + e.colorPunct("-"))
		switch {
		case item.Kind == MappingNode && item.Style&FlowStyle == 0 && len(item.Content) > 0:
			sb.WriteString(" ")
			var inner strings.Builder
			e.writeMapBody(&inner, item, indent+2)
			sb.WriteString(strings.TrimLeft(inner.String(), " "))
		case item.Kind == SequenceNode && item.Style&FlowStyle == 0 && len(item.Content) > 0:
			sb.WriteString(" ")
			var inner strings.Builder
			e.writeSeqBody(&inner, item, indent+2)
			sb.WriteString(strings.TrimLeft(inner.String(), " "))
		default:
			text := e.inlineValue(item, indent)
			if text != "" {
				sb.WriteString(" " + text)
			}
			if item.LineComment != "" {
				sb.WriteString(" " + e.colorComment("#"+item.LineComment))
			}
			sb.WriteString("\n")
		}
		e.writeComment(sb, item.FootComment, indent)
	}
}

// inlineValue renders a node so it can appear after a ":" or "-".
func (e *yamlEncoder) inlineValue(node *CandidateNode, indent int) string {
	switch node.Kind {
	case AliasNode:
		return e.colorAnchor("*" + node.Value)
	case ScalarNode:
		return e.scalarText(node, indent, false)
	case MappingNode:
		if len(node.Content) == 0 {
			return e.prefix(node) + e.colorPunct("{}")
		}
		parts := make([]string, 0, len(node.Content)/2)
		for i := 0; i+1 < len(node.Content); i += 2 {
			k := e.flowScalar(node.Content[i], indent)
			v := e.flowScalar(node.Content[i+1], indent)
			parts = append(parts, k+e.colorPunct(":")+" "+v)
		}
		return e.prefix(node) + e.colorPunct("{") + strings.Join(parts, e.colorPunct(",")+" ") + e.colorPunct("}")
	case SequenceNode:
		if len(node.Content) == 0 {
			return e.prefix(node) + e.colorPunct("[]")
		}
		parts := make([]string, 0, len(node.Content))
		for _, item := range node.Content {
			parts = append(parts, e.flowScalar(item, indent))
		}
		return e.prefix(node) + e.colorPunct("[") + strings.Join(parts, e.colorPunct(",")+" ") + e.colorPunct("]")
	}
	return ""
}

func (e *yamlEncoder) flowScalar(node *CandidateNode, indent int) string {
	if node.Kind == ScalarNode {
		return e.scalarTextFlow(node, indent)
	}
	return e.inlineValue(node, indent)
}

func (e *yamlEncoder) prefix(node *CandidateNode) string {
	out := ""
	if node.Anchor != "" {
		out += e.colorAnchor("&"+node.Anchor) + " "
	}
	if tag := visibleTag(node); tag != "" {
		out += e.colorTag(tag) + " "
	}
	return out
}

func visibleTag(node *CandidateNode) string {
	if node.Tag == "" {
		return ""
	}
	switch node.Tag {
	case TagStr, TagInt, TagFloat, TagBool, TagNull, TagMap, TagSeq, "!!timestamp", "!!merge":
		if node.Style&TaggedStyle != 0 {
			return node.Tag
		}
		return ""
	}
	return node.Tag
}

func (e *yamlEncoder) scalarText(node *CandidateNode, indent int, isKey bool) string {
	return e.prefix(node) + e.renderScalar(node, indent, false)
}

func (e *yamlEncoder) scalarTextFlow(node *CandidateNode, indent int) string {
	return e.prefix(node) + e.renderScalar(node, indent, true)
}

func (e *yamlEncoder) renderScalar(node *CandidateNode, indent int, inFlow bool) string {
	value := node.Value
	style := node.Style

	if !inFlow && style&LiteralStyle != 0 && literalAllowed(value) {
		return e.colorScalar(node, e.blockScalar(node, indent, false))
	}
	if !inFlow && style&FoldedStyle != 0 && literalAllowed(value) {
		return e.colorScalar(node, e.blockScalar(node, indent, true))
	}
	if style&DoubleQuotedStyle != 0 {
		return e.colorScalar(node, doubleQuote(value))
	}
	if style&SingleQuotedStyle != 0 && singleAllowed(value) {
		return e.colorScalar(node, singleQuote(value))
	}

	// no explicit style: work out the least noisy representation
	if value == "" {
		if node.Tag == TagNull || node.Tag == "" {
			return ""
		}
		return e.colorScalar(node, `""`)
	}
	if strings.ContainsAny(value, "\n") {
		if literalAllowed(value) && !inFlow {
			lit := *node
			lit.blockChomp = chompFor(value)
			return e.colorScalar(node, e.blockScalar(&lit, indent, false))
		}
		return e.colorScalar(node, doubleQuote(value))
	}
	if plainAllowed(value, node, inFlow) {
		return e.colorScalar(node, value)
	}
	if singleAllowed(value) {
		return e.colorScalar(node, singleQuote(value))
	}
	return e.colorScalar(node, doubleQuote(value))
}

func chompFor(value string) string {
	if !strings.HasSuffix(value, "\n") {
		return "-"
	}
	if strings.HasSuffix(value, "\n\n") {
		return "+"
	}
	return ""
}

// literalAllowed reports whether a block scalar can reproduce the value.
func literalAllowed(value string) bool {
	if value == "" {
		return false
	}
	lines := strings.Split(value, "\n")
	for i, line := range lines {
		if line == "" {
			continue
		}
		if strings.HasSuffix(line, " ") || strings.HasSuffix(line, "\t") {
			return false
		}
		if strings.TrimLeft(line, " ") == "" {
			return false
		}
		if i == 0 && (strings.HasPrefix(line, " ") || strings.HasPrefix(line, "\t")) {
			return false
		}
		for j := 0; j < len(line); j++ {
			if !printableByte(line, j) {
				return false
			}
		}
	}
	return true
}

func printableByte(s string, i int) bool {
	c := s[i]
	if c == 0x0A || (c >= 0x20 && c <= 0x7E) {
		return true
	}
	if c == 0x09 {
		return false
	}
	if c < 0x80 {
		return false
	}
	if c == 0xC2 {
		if i+1 < len(s) {
			return s[i+1] >= 0xA0
		}
		return false
	}
	if c > 0xC2 && c < 0xED {
		return true
	}
	if c == 0xED {
		if i+1 < len(s) {
			return s[i+1] < 0xA0
		}
		return false
	}
	if c == 0xEE {
		return true
	}
	if c == 0xEF {
		if i+2 < len(s) {
			if s[i+1] == 0xBB && s[i+2] == 0xBF {
				return false
			}
			if s[i+1] == 0xBF && (s[i+2] == 0xBE || s[i+2] == 0xBF) {
				return false
			}
		}
		return true
	}
	return false
}

func allPrintable(value string) bool {
	for i := 0; i < len(value); i++ {
		c := value[i]
		if c == 0x0A || (c >= 0x20 && c <= 0x7E) {
			continue
		}
		if c < 0x80 {
			return false
		}
		if !printableByte(value, i) {
			return false
		}
	}
	return true
}

// plainAllowed mirrors the emitter analysis that decides if a scalar can be
// written without quotes.
func plainAllowed(value string, node *CandidateNode, inFlow bool) bool {
	if value == "" {
		return false
	}
	if node.Tag == TagStr || node.Tag == "" {
		// a plain string must not read back as another type
		if t := guessScalarTag(value); t != TagStr {
			return false
		}
	}
	if value == "<<" {
		return false
	}
	if !allPrintable(value) {
		return false
	}
	if strings.ContainsAny(value, "\n\r\t") {
		return false
	}
	if strings.HasPrefix(value, " ") || strings.HasSuffix(value, " ") {
		return false
	}
	if value == "---" || value == "..." {
		return false
	}
	switch value[0] {
	case '#', ',', '[', ']', '{', '}', '&', '*', '!', '|', '>', '\'', '"', '%', '@', '`':
		return false
	case '-', '?', ':':
		if len(value) == 1 || value[1] == ' ' || value[1] == '\t' {
			return false
		}
	}
	if strings.Contains(value, ": ") || strings.HasSuffix(value, ":") {
		return false
	}
	if strings.Contains(value, " #") {
		return false
	}
	if inFlow && strings.ContainsAny(value, ",[]{}") {
		return false
	}
	if strings.Contains(value, " ") || strings.Contains(value, " ") || strings.Contains(value, "") {
		return false
	}
	return true
}

func singleAllowed(value string) bool {
	if strings.ContainsAny(value, "\n\r\t") {
		return false
	}
	if !allPrintable(value) {
		return false
	}
	if value == "" {
		return false
	}
	return true
}

func singleQuote(value string) string {
	return "'" + strings.ReplaceAll(value, "'", "''") + "'"
}

func doubleQuote(value string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range value {
		switch r {
		case '"':
			sb.WriteString("\\\"")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("\\n")
		case '\t':
			sb.WriteString("\\t")
		case '\r':
			sb.WriteString("\\r")
		case '\a':
			sb.WriteString("\\a")
		case '\b':
			sb.WriteString("\\b")
		case '\v':
			sb.WriteString("\\v")
		case '\f':
			sb.WriteString("\\f")
		case 0:
			sb.WriteString("\\0")
		case 0x1b:
			sb.WriteString("\\e")
		case 0x85:
			sb.WriteString("\\N")
		case 0xa0:
			sb.WriteString("\\_")
		case 0x2028:
			sb.WriteString("\\L")
		case 0x2029:
			sb.WriteString("\\P")
		default:
			if r < 0x20 {
				sb.WriteString(fmt.Sprintf("\\x%02X", r))
			} else if r > 0xFFFF {
				sb.WriteString(fmt.Sprintf("\\U%08X", r))
			} else if r == utf8.RuneError {
				sb.WriteString(fmt.Sprintf("\\u%04X", r))
			} else if r >= 0x7F && r <= 0x9F {
				sb.WriteString(fmt.Sprintf("\\x%02X", r))
			} else if r == 0xFEFF || r == 0xFFFE || r == 0xFFFF {
				sb.WriteString(fmt.Sprintf("\\u%04X", r))
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

// blockScalar renders a literal or folded scalar.
func (e *yamlEncoder) blockScalar(node *CandidateNode, indent int, folded bool) string {
	value := node.Value
	header := "|"
	if folded {
		header = ">"
	}
	chomp := node.blockChomp
	if chomp == "" {
		chomp = chompFor(value)
	}
	header += chomp

	body := value
	body = strings.TrimSuffix(body, "\n")
	if chomp == "+" {
		body = strings.TrimRight(value, "\n")
		extra := len(value) - len(body) - 1
		if extra < 0 {
			extra = 0
		}
		defer func() {}()
		body = body + strings.Repeat("\n", extra)
	}

	pad := strings.Repeat(" ", indent+e.indentWidth)
	var sb strings.Builder
	sb.WriteString(header)
	if body == "" {
		sb.WriteString("\n")
		return sb.String()
	}
	for _, line := range strings.Split(body, "\n") {
		sb.WriteString("\n")
		if line != "" {
			sb.WriteString(pad + line)
		}
	}
	sb.WriteString("\n")
	return sb.String()
}

