package yq

import (
	"fmt"
	"strings"
)

type tokKind int

const (
	tEOF tokKind = iota
	tOp
	tOpenParen
	tCloseParen
	tOpenCollect
	tCloseCollect
	tOpenObject
	tCloseObject
	tSemi
	tColon
	tValue
	tVariable
	tPath
	tSelf
	tRecurse
	tRecurseKeys
	tAs
	tRef
	tIreduce
)

type token struct {
	kind tokKind
	text string
	col  int

	// payload for value/path tokens
	node *CandidateNode
	// payload for operators
	opName string
}

type lexError struct {
	col  int
	text string
}

func (e *lexError) Error() string {
	return fmt.Sprintf("%v:%v: lexer: invalid input text \"%v\"", 1, e.col, e.text)
}

// operator spellings, longest first so that "|=" wins over "|"
var symbolOps = []string{
	"|=", "==", "!=", "<=", ">=", "+=", "-=", "*=", "/=", "%=", "//=", "//",
	"=", "|", ",", "<", ">", "+", "-", "*", "/", "%",
}

// lex converts an expression to a flat token list.
func lex(input string) ([]token, error) {
	toks := make([]token, 0, 16)
	i := 0
	n := len(input)

	prevAllowsPostfix := func() bool {
		if len(toks) == 0 {
			return false
		}
		switch toks[len(toks)-1].kind {
		case tPath, tSelf, tValue, tVariable, tCloseParen, tCloseCollect, tCloseObject, tRecurse, tRecurseKeys:
			return true
		case tOp:
			return false
		}
		return false
	}

	for i < n {
		c := input[i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			i++
			continue
		}
		col := i + 1

		// comments in expressions
		if c == '#' {
			for i < n && input[i] != '\n' {
				i++
			}
			continue
		}

		switch c {
		case '(':
			toks = append(toks, token{kind: tOpenParen, text: "(", col: col})
			i++
			continue
		case ')':
			toks = append(toks, token{kind: tCloseParen, text: ")", col: col})
			i++
			continue
		case '[':
			toks = append(toks, token{kind: tOpenCollect, text: "[", col: col})
			i++
			continue
		case ']':
			toks = append(toks, token{kind: tCloseCollect, text: "]", col: col})
			i++
			continue
		case '{':
			toks = append(toks, token{kind: tOpenObject, text: "{", col: col})
			i++
			continue
		case '}':
			toks = append(toks, token{kind: tCloseObject, text: "}", col: col})
			i++
			continue
		case ';':
			toks = append(toks, token{kind: tSemi, text: ";", col: col})
			i++
			continue
		case ':':
			toks = append(toks, token{kind: tColon, text: ":", col: col})
			i++
			continue
		case '$':
			j := i + 1
			for j < n && isVarChar(input[j]) {
				j++
			}
			if j == i+1 {
				return nil, &lexError{col: col, text: input[i:]}
			}
			toks = append(toks, token{kind: tVariable, text: input[i+1 : j], col: col})
			i = j
			continue
		case '"':
			s, adv, err := lexString(input[i:])
			if err != nil {
				return nil, &lexError{col: col, text: input[i:]}
			}
			toks = append(toks, token{kind: tValue, text: s, col: col,
				node: &CandidateNode{Kind: ScalarNode, Tag: TagStr, Value: s, Style: DoubleQuotedStyle}})
			i += adv
			continue
		case '\'':
			j := i + 1
			for j < n && input[j] != '\'' {
				j++
			}
			if j >= n {
				return nil, &lexError{col: col, text: input[i:]}
			}
			s := input[i+1 : j]
			toks = append(toks, token{kind: tValue, text: s, col: col,
				node: &CandidateNode{Kind: ScalarNode, Tag: TagStr, Value: s, Style: SingleQuotedStyle}})
			i = j + 1
			continue
		case '@':
			j := i + 1
			for j < n && isNameChar(input[j]) {
				j++
			}
			name := input[i:j]
			if _, ok := formatOps[name]; !ok {
				return nil, &lexError{col: col, text: input[i:]}
			}
			toks = append(toks, token{kind: tOp, opName: name, text: name, col: col})
			i = j
			continue
		case '.':
			tok, adv, err := lexPath(input[i:], col)
			if err != nil {
				return nil, err
			}
			toks = append(toks, tok)
			i += adv
			continue
		}

		if c >= '0' && c <= '9' {
			j := i
			for j < n && isNumberChar(input[j]) {
				j++
			}
			raw := input[i:j]
			tag := guessScalarTag(raw)
			if tag != TagInt && tag != TagFloat {
				return nil, &lexError{col: col, text: input[i:]}
			}
			toks = append(toks, token{kind: tValue, text: raw, col: col,
				node: &CandidateNode{Kind: ScalarNode, Tag: tag, Value: raw}})
			i = j
			continue
		}

		if isNameStart(c) {
			j := i
			for j < n && isNameChar(input[j]) {
				j++
			}
			word := input[i:j]
			// assignment forms such as "style=" or "headComment |="
			switch word {
			case "as":
				toks = append(toks, token{kind: tAs, text: word, col: col})
				i = j
				continue
			case "ref":
				toks = append(toks, token{kind: tRef, text: word, col: col})
				i = j
				continue
			case "ireduce", "reduce":
