func isPathChar(c byte) bool {
	switch c {
	case ' ', '\t', '\n', '\r', '.', '(', ')', '[', ']', '{', '}', ',', ';', ':', '|', '=', '!', '?':
		return false
	}
	return c > 32 && c < 127 || c >= 128
}

// lexString reads a double quoted string with escapes, returning the raw text
// (interpolation is resolved later).
func lexString(input string) (string, int, error) {
	var sb strings.Builder
	i := 1
	for i < len(input) {
		c := input[i]
		if c == '\\' && i+1 < len(input) {
			nxt := input[i+1]
			switch nxt {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteString("\\\\")
			case '(':
				sb.WriteString("\\(")
			default:
				sb.WriteByte('\\')
				sb.WriteByte(nxt)
			}
			i += 2
			continue
		}
		if c == '"' {
			return sb.String(), i + 1, nil
		}
		sb.WriteByte(c)
		i++
	}
	return "", 0, fmt.Errorf("unterminated string")
}

