package yq

import (
	"fmt"
)

// ExpressionNode is a node of the parsed expression tree.
type ExpressionNode struct {
	Operation *Operation
	Lhs       *ExpressionNode
	Rhs       *ExpressionNode
	// extra arguments for function style operators (arg1; arg2; ...)
	Args []*ExpressionNode
}

// Operation describes what an expression node does.
type Operation struct {
	Type        *operationType
	Value       *CandidateNode
	StringValue string
	Prefs       interface{}
}

type opHandler func(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error)

type operationType struct {
	Name    string
	NumArgs int
	Handler opHandler
}

type parser struct {
	toks []token
	pos  int
}

// ParseExpression turns an expression string into a tree.
func ParseExpression(expression string) (*ExpressionNode, error) {
	if expression == "" {
		return &ExpressionNode{Operation: &Operation{Type: opSelf}}, nil
	}
	toks, err := lex(expression)
	if err != nil {
		return nil, err
	}
	p := &parser{toks: toks}
	node, err := p.parseUnion()
	if err != nil {
		return nil, err
	}
	if p.cur().kind != tEOF {
		return nil, fmt.Errorf("bad expression, please check expression syntax")
	}
	return node, nil
}

func (p *parser) cur() token  { return p.toks[p.pos] }
func (p *parser) next() token { t := p.toks[p.pos]; p.pos++; return t }

func (p *parser) isOp(names ...string) bool {
	t := p.cur()
	if t.kind != tOp {
		return false
	}
	for _, n := range names {
		if t.opName == n {
			return true
		}
	}
	return false
}

func binary(name string, lhs, rhs *ExpressionNode) (*ExpressionNode, error) {
	ot, ok := allOps[name]
	if !ok {
		return nil, fmt.Errorf("bad expression, please check expression syntax")
	}
	return &ExpressionNode{Operation: &Operation{Type: ot}, Lhs: lhs, Rhs: rhs}, nil
}

func (p *parser) parseUnion() (*ExpressionNode, error) {
	lhs, err := p.parsePipe()
	if err != nil {
		return nil, err
	}
	for p.isOp(",") {
		p.next()
		rhs, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		lhs, err = binary(",", lhs, rhs)
		if err != nil {
			return nil, err
		}
	}
	return lhs, nil
}

func (p *parser) parsePipe() (*ExpressionNode, error) {
	lhs, err := p.parseAs()
	if err != nil {
		return nil, err
	}
	for p.isOp("|") {
		p.next()
		rhs, err := p.parseAs()
		if err != nil {
			return nil, err
		}
		lhs, err = binary("|", lhs, rhs)
		if err != nil {
			return nil, err
		}
	}
	return lhs, nil
}

func (p *parser) parseAs() (*ExpressionNode, error) {
	lhs, err := p.parseBool()
	if err != nil {
		return nil, err
	}
	kind := p.cur().kind
	if kind != tAs && kind != tRef {
		return lhs, nil
	}
	isRef := kind == tRef
	p.next()
	if p.cur().kind != tVariable {
		return nil, fmt.Errorf("RHS of 'as' operator must be a variable name e.g. $foo")
	}
	varTok := p.next()
	varNode := &ExpressionNode{Operation: &Operation{Type: opGetVariable, StringValue: varTok.text}}

	name := "as"
	if isRef {
		name = "ref"
	}
	asNode := &ExpressionNode{
		Operation: &Operation{Type: allOps[name], StringValue: varTok.text},
		Lhs:       lhs,
		Rhs:       varNode,
	}

	if p.cur().kind == tIreduce {
		p.next()
		if p.cur().kind != tOpenParen {
			return nil, fmt.Errorf("'ireduce' expects 2 args but there is 0")
		}
		p.next()
		initExp, err := p.parseUnion()
		if err != nil {
			return nil, err
		}
		if p.cur().kind != tSemi {
			return nil, fmt.Errorf("'ireduce' expects 2 args but there is 1")
		}
		p.next()
		updateExp, err := p.parseUnion()
		if err != nil {
			return nil, err
		}
		if p.cur().kind != tCloseParen {
			return nil, fmt.Errorf("bad expression, please check expression syntax")
		}
		p.next()
		return &ExpressionNode{
			Operation: &Operation{Type: allOps["ireduce"]},
			Lhs:       asNode,
			Rhs:       initExp,
			Args:      []*ExpressionNode{updateExp},
		}, nil
	}

	if p.isOp("|") {
		p.next()
		body, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		asNode.Args = []*ExpressionNode{body}
	}
	return asNode, nil
}

func (p *parser) parseBool() (*ExpressionNode, error) {
	lhs, err := p.parseAssign()
	if err != nil {
		return nil, err
	}
	if p.isOp("and") || p.isOp("or") {
		name := p.next().opName
		rhs, err := p.parseBool()
		if err != nil {
			return nil, err
		}
		return binary(name, lhs, rhs)
	}
	return lhs, nil
}

var assignOps = []string{"=", "|=", "+=", "-=", "*=", "/=", "%=", "//="}

func (p *parser) parseAssign() (*ExpressionNode, error) {
	lhs, err := p.parseAlternative()
	if err != nil {
		return nil, err
	}
	if p.isOp(assignOps...) {
		name := p.next().opName
		rhs, err := p.parseAlternative()
		if err != nil {
			return nil, err
		}
		// meta assignment: "style = x", "tag |= x", ...
		if lhs != nil && lhs.Operation != nil && lhs.Operation.Type.Name != "" {
			if meta, ok := metaAssignFor(lhs.Operation.Type.Name, name); ok {
				return &ExpressionNode{Operation: &Operation{Type: meta}, Lhs: lhs.Lhs, Rhs: rhs}, nil
			}
		}
		return binary(name, lhs, rhs)
	}
	return lhs, nil
}

func (p *parser) parseAlternative() (*ExpressionNode, error) {
	lhs, err := p.parseComparison()
	if err != nil {
		return nil, err
	}
	for p.isOp("//") {
		p.next()
		rhs, err := p.parseComparison()
		if err != nil {
			return nil, err
		}
		lhs, err = binary("//", lhs, rhs)
		if err != nil {
			return nil, err
		}
	}
	return lhs, nil
}

func (p *parser) parseComparison() (*ExpressionNode, error) {
	lhs, err := p.parseAdditive()
	if err != nil {
		return nil, err
	}
	for p.isOp("==", "!=", "<", ">", "<=", ">=") {
		name := p.next().opName
		rhs, err := p.parseAdditive()
		if err != nil {
			return nil, err
		}
		lhs, err = binary(name, lhs, rhs)
		if err != nil {
			return nil, err
		}
	}
	return lhs, nil
}

func (p *parser) parseAdditive() (*ExpressionNode, error) {
	lhs, err := p.parseMultiplicative()
	if err != nil {
		return nil, err
	}
	for p.isOp("+", "-") {
		name := p.next().opName
		rhs, err := p.parseMultiplicative()
		if err != nil {
			return nil, err
		}
		lhs, err = binary(name, lhs, rhs)
		if err != nil {
			return nil, err
		}
	}
	return lhs, nil
}

func (p *parser) parseMultiplicative() (*ExpressionNode, error) {
	lhs, err := p.parsePostfix()
	if err != nil {
		return nil, err
	}
	for p.isOp("*", "/", "%") {
		name := p.next().opName
		rhs, err := p.parsePostfix()
		if err != nil {
			return nil, err
		}
		lhs, err = binary(name, lhs, rhs)
		if err != nil {
			return nil, err
		}
	}
	return lhs, nil
}

// parsePostfix handles chained traversals: .a.b[0][].c
func (p *parser) parsePostfix() (*ExpressionNode, error) {
	lhs, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	for {
		switch {
		case p.cur().kind == tPath || p.cur().kind == tSelf:
			if p.cur().kind == tSelf {
				return lhs, nil
			}
			tok := p.next()
			trav := &ExpressionNode{Operation: &Operation{
				Type: opTraversePath, Value: tok.node, StringValue: tok.text,
			}}
			lhs, err = binary("|", lhs, trav)
			if err != nil {
				return nil, err
			}
		case p.cur().kind == tRecurse:
			p.next()
			rec := &ExpressionNode{Operation: &Operation{Type: opRecurseValues}}
			lhs, err = binary("|", lhs, rec)
			if err != nil {
				return nil, err
			}
		case p.cur().kind == tOpenCollect:
			p.next()
			if p.cur().kind == tCloseCollect {
				p.next()
				sp := &ExpressionNode{Operation: &Operation{Type: opSplat}}
				lhs, err = binary("|", lhs, sp)
				if err != nil {
					return nil, err
				}
				lhs = p.maybeOptional(lhs)
				continue
			}
			idx, err := p.parseIndexArgs()
			if err != nil {
				return nil, err
			}
			lhs, err = binary("|", lhs, idx)
			if err != nil {
				return nil, err
			}
		default:
			return lhs, nil
		}
		lhs = p.maybeOptional(lhs)
	}
}

func (p *parser) maybeOptional(lhs *ExpressionNode) *ExpressionNode {
	if p.cur().kind == tOp && p.cur().opName == "?" {
		p.next()
	}
	return lhs
}

// parseIndexArgs handles [expr], [a:b] and the open ended slice forms.
func (p *parser) parseIndexArgs() (*ExpressionNode, error) {
	var from, to *ExpressionNode
	var err error
	isSlice := false

	if p.cur().kind != tColon {
		from, err = p.parseUnion()
		if err != nil {
			return nil, err
		}
	}
	if p.cur().kind == tColon {
		isSlice = true
		p.next()
		if p.cur().kind != tCloseCollect {
			to, err = p.parseUnion()
			if err != nil {
				return nil, err
			}
		}
	}
	if p.cur().kind != tCloseCollect {
		return nil, fmt.Errorf("bad expression, please check expression syntax")
	}
	p.next()
	if isSlice {
		return &ExpressionNode{
			Operation: &Operation{Type: opSlice},
			Lhs:       from,
			Rhs:       to,
		}, nil
	}
	return &ExpressionNode{Operation: &Operation{Type: opTraverseExpr}, Rhs: from}, nil
}

func (p *parser) parsePrimary() (*ExpressionNode, error) {
	tok := p.cur()
	switch tok.kind {
	case tOpenParen:
		p.next()
		inner, err := p.parseUnion()
		if err != nil {
			return nil, err
		}
		if p.cur().kind != tCloseParen {
			return nil, fmt.Errorf("bad expression, please check expression syntax")
		}
		p.next()
		return inner, nil
	case tOpenCollect:
		p.next()
		if p.cur().kind == tCloseCollect {
			p.next()
			return &ExpressionNode{Operation: &Operation{Type: opCollect}}, nil
		}
		inner, err := p.parseUnion()
		if err != nil {
			return nil, err
		}
		if p.cur().kind != tCloseCollect {
			return nil, fmt.Errorf("bad expression, please check expression syntax")
		}
		p.next()
		return &ExpressionNode{Operation: &Operation{Type: opCollect}, Rhs: inner}, nil
	case tOpenObject:
		p.next()
		if p.cur().kind == tCloseObject {
			p.next()
			return &ExpressionNode{Operation: &Operation{Type: opCollectObject}}, nil
		}
		inner, err := p.parseObjectBody()
		if err != nil {
			return nil, err
		}
		if p.cur().kind != tCloseObject {
			return nil, fmt.Errorf("bad expression, please check expression syntax")
		}
		p.next()
		return &ExpressionNode{Operation: &Operation{Type: opCollectObject}, Rhs: inner}, nil
	case tValue:
		p.next()
		return &ExpressionNode{Operation: &Operation{Type: opValue, Value: tok.node, StringValue: tok.text}}, nil
	case tVariable:
		p.next()
		return &ExpressionNode{Operation: &Operation{Type: opGetVariable, StringValue: tok.text}}, nil
	case tSelf:
		p.next()
		return &ExpressionNode{Operation: &Operation{Type: opSelf}}, nil
	case tPath:
		p.next()
		return &ExpressionNode{Operation: &Operation{
			Type: opTraversePath, Value: tok.node, StringValue: tok.text,
		}}, nil
	case tRecurse:
		p.next()
		return &ExpressionNode{Operation: &Operation{Type: opRecurseValues}}, nil
	case tRecurseKeys:
		p.next()
		return &ExpressionNode{Operation: &Operation{Type: opRecurseAll}}, nil
	case tOp:
		if ot, ok := namedOps[tok.opName]; ok {
			p.next()
			return p.parseCall(ot, tok)
		}
		if ot, ok := formatOps[tok.opName]; ok {
			p.next()
			return &ExpressionNode{Operation: &Operation{Type: ot}}, nil
		}
		if tok.opName == "-" {
			// unary minus
			p.next()
			operand, err := p.parsePostfix()
			if err != nil {
				return nil, err
			}
			zero := &ExpressionNode{Operation: &Operation{Type: opValue,
				Value: &CandidateNode{Kind: ScalarNode, Tag: TagInt, Value: "0"}}}
			return binary("-", zero, operand)
		}
	}
	return nil, fmt.Errorf("bad expression, please check expression syntax")
}

// parseObjectBody reads the key: value pairs of an object construction.
func (p *parser) parseObjectBody() (*ExpressionNode, error) {
	var result *ExpressionNode
	for {
		key, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		if p.cur().kind != tColon {
			return nil, fmt.Errorf("bad expression, please check expression syntax")
		}
		p.next()
		value, err := p.parsePipe()
		if err != nil {
			return nil, err
		}
		pair := &ExpressionNode{Operation: &Operation{Type: opCreateMap}, Lhs: key, Rhs: value}
		if result == nil {
			result = pair
		} else {
			result, err = binary(",", result, pair)
			if err != nil {
				return nil, err
			}
		}
		if p.isOp(",") {
			p.next()
			continue
		}
		return result, nil
	}
}

// parseCall reads the optional (arg; arg) list of a named operator.
func (p *parser) parseCall(ot *operationType, tok token) (*ExpressionNode, error) {
	if p.cur().kind != tOpenParen {
		if ot.NumArgs > 0 {
			if ot.NumArgs == 1 {
				return nil, fmt.Errorf("'%v' expects 1 arg but received none", ot.Name)
			}
			return nil, fmt.Errorf("'%v' expects %v args but there is 0", ot.Name, ot.NumArgs)
		}
		return &ExpressionNode{Operation: &Operation{Type: ot, StringValue: tok.text}}, nil
	}
	p.next()
	args := make([]*ExpressionNode, 0, 2)
	if p.cur().kind != tCloseParen {
		for {
			arg, err := p.parseUnion()
			if err != nil {
				return nil, err
			}
			args = append(args, arg)
			if p.cur().kind == tSemi {
				p.next()
				continue
			}
			break
		}
	}
	if p.cur().kind != tCloseParen {
		return nil, fmt.Errorf("bad expression, please check expression syntax")
	}
	p.next()
	if ot.NumArgs > 0 && len(args) < ot.NumArgs {
		if ot.NumArgs == 1 {
			return nil, fmt.Errorf("'%v' expects 1 arg but received none", ot.Name)
		}
		return nil, fmt.Errorf("'%v' expects %v args but there is %v", ot.Name, ot.NumArgs, len(args))
	}
	node := &ExpressionNode{Operation: &Operation{Type: ot, StringValue: tok.text}}
	if len(args) > 0 {
		node.Rhs = args[0]
		node.Args = args
	}
	return node, nil
}

