package yq

import (
	"fmt"
)

// Context is the working set of an expression evaluation step.
type Context struct {
	MatchingNodes  []*CandidateNode
	Variables      map[string][]*CandidateNode
	DontAutoCreate bool
}

func newContext(nodes ...*CandidateNode) Context {
	return Context{MatchingNodes: nodes, Variables: map[string][]*CandidateNode{}}
}

func (c Context) SingleChildContext(node *CandidateNode) Context {
	return c.ChildContext([]*CandidateNode{node})
}

func (c Context) ChildContext(nodes []*CandidateNode) Context {
	clone := c
	clone.MatchingNodes = nodes
	return clone
}

func (c Context) ReadOnlyClone() Context {
	clone := c
	clone.DontAutoCreate = true
	return clone
}

func (c Context) WritableClone() Context {
	clone := c
	clone.DontAutoCreate = false
	return clone
}

func (c *Context) SetVariable(name string, value []*CandidateNode) {
	if c.Variables == nil {
		c.Variables = map[string][]*CandidateNode{}
	}
	// copy on write so sibling branches don't see each other's bindings
	next := make(map[string][]*CandidateNode, len(c.Variables)+1)
	for k, v := range c.Variables {
		next[k] = v
	}
	next[name] = value
	c.Variables = next
}

func (c Context) GetVariable(name string) []*CandidateNode {
	if c.Variables == nil {
		return nil
	}
	return c.Variables[name]
}

// dataTreeNavigator walks the expression tree.
type dataTreeNavigator struct{}

func (d *dataTreeNavigator) GetMatchingNodes(context Context, expressionNode *ExpressionNode) (Context, error) {
	if expressionNode == nil {
		return context, nil
	}
	if expressionNode.Operation == nil || expressionNode.Operation.Type == nil {
		return context, fmt.Errorf("bad expression, please check expression syntax")
	}
	handler := expressionNode.Operation.Type.Handler
	if handler == nil {
		return context, fmt.Errorf("operator %v is not implemented", expressionNode.Operation.Type.Name)
	}
	return handler(d, context, expressionNode)
}

// Evaluator runs expressions over candidate nodes.
type Evaluator struct {
	nav *dataTreeNavigator
}

func NewEvaluator() *Evaluator { return &Evaluator{nav: &dataTreeNavigator{}} }

func (e *Evaluator) EvaluateNodes(expression *ExpressionNode, nodes ...*CandidateNode) ([]*CandidateNode, error) {
	context, err := e.nav.GetMatchingNodes(newContext(nodes...), expression)
	if err != nil {
		return nil, err
	}
	return context.MatchingNodes, nil
}

// helpers -------------------------------------------------------------------

func createBooleanCandidate(owner *CandidateNode, value bool) *CandidateNode {
	valString := "false"
	if value {
		valString = "true"
	}
	node := owner.CreateReplacement(ScalarNode, TagBool, valString)
	return node
}

func createStringScalarNode(stringValue string) *CandidateNode {
	return &CandidateNode{Kind: ScalarNode, Tag: TagStr, Value: stringValue}
}

func createIntScalarNode(value int) *CandidateNode {
	return &CandidateNode{Kind: ScalarNode, Tag: TagInt, Value: fmt.Sprintf("%v", value)}
}

func createNullScalarNode() *CandidateNode {
	return &CandidateNode{Kind: ScalarNode, Tag: TagNull, Value: "null"}
}

func isTruthy(node *CandidateNode) (bool, error) {
	if node == nil {
		return false, nil
	}
	if node.Kind != ScalarNode {
		return true, nil
	}
	switch node.Tag {
	case TagNull, "!!~":
		return false, nil
	case TagBool:
		return node.Value == "true" || node.Value == "True" || node.Value == "TRUE", nil
	}
	return true, nil
}

