package yq

import (
	"fmt"
	"strconv"
	"strings"
)

// ---------------------------------------------------------------------------
// structural operators
// ---------------------------------------------------------------------------

func selfOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	return context, nil
}

func pipeOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, node.Lhs)
	if err != nil {
		return Context{}, err
	}
	return d.GetMatchingNodes(lhs, node.Rhs)
}

func unionOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, node.Lhs)
	if err != nil {
		return Context{}, err
	}
	rhs, err := d.GetMatchingNodes(context, node.Rhs)
	if err != nil {
		return Context{}, err
	}
	return context.ChildContext(append(append([]*CandidateNode{}, lhs.MatchingNodes...), rhs.MatchingNodes...)), nil
}

func valueOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	value := node.Operation.Value
	if value != nil && value.Tag == TagStr && strings.Contains(value.Value, "\\(") {
		results := make([]*CandidateNode, 0, len(context.MatchingNodes))
		if len(context.MatchingNodes) == 0 {
			return context.ChildContext(results), nil
		}
		for _, candidate := range context.MatchingNodes {
			text, err := interpolate(d, context.SingleChildContext(candidate), value.Value)
			if err != nil {
				return Context{}, err
			}
			clone := value.Copy()
			clone.Value = text
			results = append(results, clone)
		}
		return context.ChildContext(results), nil
	}
	if value == nil {
		return context.ChildContext(nil), nil
	}
	clone := value.Copy()
	clone.Value = unescapeLiteral(clone.Value)
	return context.ChildContext([]*CandidateNode{clone}), nil
}

func unescapeLiteral(value string) string {
	return strings.ReplaceAll(value, "\\\\", "\\")
}

// interpolate resolves \(expr) sequences inside a string literal.
func interpolate(d *dataTreeNavigator, context Context, raw string) (string, error) {
	var sb strings.Builder
	i := 0
	for i < len(raw) {
		if raw[i] == '\\' && i+1 < len(raw) {
			if raw[i+1] == '(' {
				depth := 1
				j := i + 2
				for j < len(raw) && depth > 0 {
					if raw[j] == '(' {
						depth++
					} else if raw[j] == ')' {
						depth--
					}
					j++
				}
				if depth != 0 {
					return "", fmt.Errorf("bad expression, please check expression syntax")
				}
				inner := raw[i+2 : j-1]
				exp, err := ParseExpression(inner)
				if err != nil {
					return "", err
				}
				result, err := d.GetMatchingNodes(context, exp)
				if err != nil {
					return "", err
				}
				for _, n := range result.MatchingNodes {
					sb.WriteString(nodeToString(n))
				}
				i = j
				continue
			}
			if raw[i+1] == '\\' {
				sb.WriteByte('\\')
				i += 2
				continue
			}
		}
		sb.WriteByte(raw[i])
		i++
	}
	return sb.String(), nil
}

func nodeToString(node *CandidateNode) string {
	if node.Kind == ScalarNode {
		return node.Value
	}
	out, err := encodeToString(node, "yaml", 2, false)
	if err != nil {
		return ""
	}
	return strings.TrimSuffix(out, "\n")
}

// ---------------------------------------------------------------------------
// traversal
// ---------------------------------------------------------------------------

func traversePathOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	key := node.Operation.Value
	results := make([]*CandidateNode, 0)
	for _, candidate := range context.MatchingNodes {
		matches, err := traverse(context, candidate, key)
		if err != nil {
			return Context{}, err
		}
		results = append(results, matches...)
	}
	return context.ChildContext(results), nil
}

func traverseExprOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), node.Rhs)
	if err != nil {
		return Context{}, err
	}
	results := make([]*CandidateNode, 0)
	for _, candidate := range context.MatchingNodes {
		for _, key := range rhs.MatchingNodes {
			if key.Kind == SequenceNode {
				// .[ [a,b] ] walks a path
				current := []*CandidateNode{candidate}
				for _, step := range key.Content {
					nxt := make([]*CandidateNode, 0)
					for _, c := range current {
						m, err := traverse(context, c, step)
						if err != nil {
							return Context{}, err
						}
						nxt = append(nxt, m...)
					}
					current = nxt
				}
				results = append(results, current...)
				continue
			}
			matches, err := traverse(context, candidate, key)
			if err != nil {
				return Context{}, err
			}
			results = append(results, matches...)
		}
	}
	return context.ChildContext(results), nil
}

// traverse resolves a single key against a node.
func traverse(context Context, candidate *CandidateNode, key *CandidateNode) ([]*CandidateNode, error) {
	switch candidate.Kind {
	case MappingNode:
		return traverseMap(context, candidate, key)
	case SequenceNode:
		return traverseSeq(context, candidate, key)
	case AliasNode:
		if candidate.Alias != nil {
			return traverse(context, candidate.Alias, key)
		}
		return nil, nil
	case ScalarNode:
		if candidate.Tag == TagNull || candidate.Value == "" && candidate.Tag == "" {
			if context.DontAutoCreate {
				return []*CandidateNode{createNullChild(candidate, key)}, nil
			}
			// nulls turn into the collection the key implies
			if key.Tag == TagInt {
				candidate.Kind = SequenceNode
				candidate.Tag = TagSeq
				candidate.Value = ""
				return traverseSeq(context, candidate, key)
			}
			candidate.Kind = MappingNode
			candidate.Tag = TagMap
			candidate.Value = ""
			return traverseMap(context, candidate, key)
		}
		return nil, fmt.Errorf("cannot index %v with %v", candidate.GetNiceTag(), key.Value)
	}
	return nil, nil
}

func createNullChild(parent *CandidateNode, key *CandidateNode) *CandidateNode {
	child := &CandidateNode{
		Kind: ScalarNode, Tag: TagNull, Value: "null",
		Parent: parent, Key: key.Copy(),
		Document: parent.Document, Filename: parent.Filename, FileIndex: parent.FileIndex,
	}
	return child
}

func traverseMap(context Context, candidate *CandidateNode, key *CandidateNode) ([]*CandidateNode, error) {
	if key.Kind != ScalarNode {
		return nil, nil
	}
	wanted := key.Value
	results := make([]*CandidateNode, 0, 1)

	if strings.Contains(wanted, "*") && key.Tag == TagStr {
		pattern := wanted
		for i := 0; i+1 < len(candidate.Content); i += 2 {
			if globMatch(pattern, candidate.Content[i].Value) {
				results = append(results, candidate.Content[i+1])
			}
		}
		if len(results) > 0 {
			return results, nil
		}
		if strings.ContainsAny(pattern, "*") {
			return results, nil
		}
	}

	for i := 0; i+1 < len(candidate.Content); i += 2 {
		if candidate.Content[i].Value == wanted {
			return []*CandidateNode{candidate.Content[i+1]}, nil
		}
	}
	// follow merge keys
	if merged := traverseMergeKeys(candidate, wanted); merged != nil {
		return []*CandidateNode{merged}, nil
	}

	child := createNullChild(candidate, key)
	if context.DontAutoCreate {
		return []*CandidateNode{child}, nil
	}
	keyCopy := key.Copy()
	keyCopy.Tag = TagStr
	candidate.AddKeyValueChild(keyCopy, child)
	child.Key = keyCopy
	return []*CandidateNode{child}, nil
}

func traverseMergeKeys(candidate *CandidateNode, wanted string) *CandidateNode {
	for i := 0; i+1 < len(candidate.Content); i += 2 {
		if candidate.Content[i].Value != "<<" {
			continue
		}
		value := candidate.Content[i+1]
		targets := []*CandidateNode{value}
		if value.Kind == SequenceNode {
			targets = value.Content
		}
		for _, target := range targets {
			resolved := target
			if resolved.Kind == AliasNode && resolved.Alias != nil {
				resolved = resolved.Alias
			}
			if resolved.Kind != MappingNode {
				continue
			}
			for j := 0; j+1 < len(resolved.Content); j += 2 {
				if resolved.Content[j].Value == wanted {
					return resolved.Content[j+1]
				}
			}
		}
	}
	return nil
}

// globMatch is a simple "*" wildcard matcher used for key lookups.
func globMatch(pattern, value string) bool {
	parts := strings.Split(pattern, "*")
	if len(parts) == 1 {
		return pattern == value
	}
	if !strings.HasPrefix(value, parts[0]) {
		return false
	}
	rest := value[len(parts[0]):]
	for i := 1; i < len(parts)-1; i++ {
		idx := strings.Index(rest, parts[i])
		if idx < 0 {
			return false
		}
		rest = rest[idx+len(parts[i]):]
	}
	last := parts[len(parts)-1]
	return strings.HasSuffix(rest, last) || last == ""
}

func traverseSeq(context Context, candidate *CandidateNode, key *CandidateNode) ([]*CandidateNode, error) {
	if key.Value == "[]" {
		return candidate.Content, nil
	}
	index, err := strconv.Atoi(key.Value)
	if err != nil {
		if key.Tag == TagStr {
			return nil, fmt.Errorf("cannot index array with '%v'", key.Value)
		}
		return nil, fmt.Errorf("cannot index array with %v", key.Value)
	}
	if index < 0 {
		if -index > len(candidate.Content) {
			return nil, fmt.Errorf("index [%v] out of range, array size is %v", index, len(candidate.Content))
		}
		return []*CandidateNode{candidate.Content[len(candidate.Content)+index]}, nil
	}
	if index >= len(candidate.Content) {
		if context.DontAutoCreate {
			return []*CandidateNode{createNullChild(candidate, key)}, nil
		}
		for len(candidate.Content) <= index {
			candidate.AddChild(&CandidateNode{Kind: ScalarNode, Tag: TagNull, Value: "null"})
		}
	}
	return []*CandidateNode{candidate.Content[index]}, nil
}

func splatOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	results := make([]*CandidateNode, 0)
	for _, candidate := range context.MatchingNodes {
		switch candidate.Kind {
		case SequenceNode:
			results = append(results, candidate.Content...)
		case MappingNode:
			for i := 1; i < len(candidate.Content); i += 2 {
				results = append(results, candidate.Content[i])
			}
		case ScalarNode:
			if candidate.Tag == TagNull {
				continue
			}
			return Context{}, fmt.Errorf("cannot splat %v", candidate.GetNiceTag())
		}
	}
	return context.ChildContext(results), nil
}

func sliceOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	results := make([]*CandidateNode, 0)
	for _, candidate := range context.MatchingNodes {
		from := 0
		to := -1
		if candidate.Kind == SequenceNode {
			to = len(candidate.Content)
		} else if candidate.Kind == ScalarNode {
			to = len([]rune(candidate.Value))
		}
		var err error
		if node.Lhs != nil {
			from, err = evalIndexArg(d, context, candidate, node.Lhs, to)
			if err != nil {
				return Context{}, err
			}
		}
		if node.Rhs != nil {
			to, err = evalIndexArg(d, context, candidate, node.Rhs, to)
			if err != nil {
				return Context{}, err
			}
		}
		switch candidate.Kind {
		case SequenceNode:
			from, to = clampRange(from, to, len(candidate.Content))
			clone := candidate.CopyWithoutContent()
			clone.Content = nil
			for _, item := range candidate.Content[from:to] {
				clone.AddChild(item.Copy())
			}
			results = append(results, clone)
		case ScalarNode:
			runes := []rune(candidate.Value)
			from, to = clampRange(from, to, len(runes))
			clone := candidate.CopyWithoutContent()
			clone.Value = string(runes[from:to])
			results = append(results, clone)
		default:
			return Context{}, fmt.Errorf("cannot slice %v", candidate.GetNiceTag())
		}
	}
	return context.ChildContext(results), nil
}

func clampRange(from, to, length int) (int, int) {
	if from < 0 {
		from = length + from
	}
	if to < 0 {
		to = length + to
	}
	if from < 0 {
		from = 0
	}
	if to > length {
		to = length
	}
	if from > length {
		from = length
	}
	if to < from {
		to = from
	}
	return from, to
}

func evalIndexArg(d *dataTreeNavigator, context Context, candidate *CandidateNode, exp *ExpressionNode, fallback int) (int, error) {
	result, err := d.GetMatchingNodes(context.SingleChildContext(candidate).ReadOnlyClone(), exp)
	if err != nil {
		return 0, err
	}
	if len(result.MatchingNodes) == 0 {
		return fallback, nil
	}
	value := result.MatchingNodes[0]
	n, err := strconv.Atoi(value.Value)
	if err != nil {
		return 0, fmt.Errorf("cannot use %v as an index", value.Value)
	}
	return n, nil
}

// ---------------------------------------------------------------------------
// recursion
// ---------------------------------------------------------------------------

func recurseValuesOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	results := make([]*CandidateNode, 0)
	for _, candidate := range context.MatchingNodes {
		results = appendRecurse(results, candidate, false)
	}
	return context.ChildContext(results), nil
}

func recurseAllOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	results := make([]*CandidateNode, 0)
	for _, candidate := range context.MatchingNodes {
		results = appendRecurse(results, candidate, true)
	}
	return context.ChildContext(results), nil
}

func appendRecurse(results []*CandidateNode, node *CandidateNode, includeKeys bool) []*CandidateNode {
	results = append(results, node)
	switch node.Kind {
	case MappingNode:
		for i := 0; i+1 < len(node.Content); i += 2 {
			if includeKeys {
				results = appendRecurse(results, node.Content[i], includeKeys)
			}
			results = appendRecurse(results, node.Content[i+1], includeKeys)
		}
	case SequenceNode:
		for _, child := range node.Content {
			results = appendRecurse(results, child, includeKeys)
		}
	}
	return results
}

// ---------------------------------------------------------------------------
// collect
// ---------------------------------------------------------------------------

func collectOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	if node.Rhs == nil {
		empty := &CandidateNode{Kind: SequenceNode, Tag: TagSeq, Style: FlowStyle}
		return context.ChildContext([]*CandidateNode{empty}), nil
	}
	if len(context.MatchingNodes) == 0 {
		result := &CandidateNode{Kind: SequenceNode, Tag: TagSeq}
		rhs, err := d.GetMatchingNodes(context, node.Rhs)
		if err != nil {
			return Context{}, err
		}
		for _, n := range rhs.MatchingNodes {
			result.AddChild(n.Copy())
		}
		return context.ChildContext([]*CandidateNode{result}), nil
	}
	results := make([]*CandidateNode, 0, len(context.MatchingNodes))
	for _, candidate := range context.MatchingNodes {
		rhs, err := d.GetMatchingNodes(context.SingleChildContext(candidate), node.Rhs)
		if err != nil {
			return Context{}, err
		}
		result := &CandidateNode{Kind: SequenceNode, Tag: TagSeq,
			Document: candidate.Document, Filename: candidate.Filename, FileIndex: candidate.FileIndex}
		for _, n := range rhs.MatchingNodes {
			result.AddChild(n.Copy())
		}
		results = append(results, result)
	}
	return context.ChildContext(results), nil
}

func collectObjectOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	if node.Rhs == nil {
		empty := &CandidateNode{Kind: MappingNode, Tag: TagMap, Style: FlowStyle}
		return context.ChildContext([]*CandidateNode{empty}), nil
	}
	if len(context.MatchingNodes) == 0 {
		return collectObjectFor(d, context, node, nil)
	}
	results := make([]*CandidateNode, 0, len(context.MatchingNodes))
	for _, candidate := range context.MatchingNodes {
		ctx, err := collectObjectFor(d, context.SingleChildContext(candidate), node, candidate)
		if err != nil {
			return Context{}, err
		}
		results = append(results, ctx.MatchingNodes...)
	}
	return context.ChildContext(results), nil
}

func collectObjectFor(d *dataTreeNavigator, context Context, node *ExpressionNode, candidate *CandidateNode) (Context, error) {
	rhs, err := d.GetMatchingNodes(context, node.Rhs)
	if err != nil {
		return Context{}, err
	}
	// each entry produced by the RHS is a single pair map; the cartesian
	// product of alternatives is merged into one object
	combined := []*CandidateNode{{Kind: MappingNode, Tag: TagMap}}
	for _, entry := range rhs.MatchingNodes {
		next := make([]*CandidateNode, 0, len(combined))
		for _, base := range combined {
			clone := base.Copy()
			for i := 0; i+1 < len(entry.Content); i += 2 {
				setMapEntry(clone, entry.Content[i].Copy(), entry.Content[i+1].Copy())
			}
			next = append(next, clone)
		}
		combined = next
	}
	return context.ChildContext(combined), nil
}

func setMapEntry(m *CandidateNode, key, value *CandidateNode) {
	for i := 0; i+1 < len(m.Content); i += 2 {
		if m.Content[i].Value == key.Value {
			value.Parent = m
			value.Key = m.Content[i]
			m.Content[i+1] = value
			return
		}
	}
	m.AddKeyValueChild(key, value)
}

// createMapOperator builds the single pair maps used by object construction.
func createMapOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	results := make([]*CandidateNode, 0)
	keys, err := d.GetMatchingNodes(context.ReadOnlyClone(), node.Lhs)
	if err != nil {
		return Context{}, err
	}
	for _, key := range keys.MatchingNodes {
		values, err := d.GetMatchingNodes(context, node.Rhs)
		if err != nil {
			return Context{}, err
		}
		for _, value := range values.MatchingNodes {
			m := &CandidateNode{Kind: MappingNode, Tag: TagMap}
			keyCopy := key.Copy()
			keyCopy.Style = 0
			if keyCopy.Kind != ScalarNode {
				continue
			}
			m.AddKeyValueChild(keyCopy, value.Copy())
			results = append(results, m)
		}
	}
	return context.ChildContext(results), nil
}

// ---------------------------------------------------------------------------
// variables
// ---------------------------------------------------------------------------

func getVariableOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	name := node.Operation.StringValue
	value := context.GetVariable(name)
	if value == nil {
		value = context.GetVariable(strings.TrimPrefix(name, "$"))
	}
	if value == nil {
		return context.ChildContext(nil), nil
	}
	return context.ChildContext(value), nil
}

func assignVariableOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	name := node.Operation.StringValue
	isRef := node.Operation.Type.Name == "ref"

	lhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), node.Lhs)
	if err != nil {
		return Context{}, err
	}

	body := (*ExpressionNode)(nil)
	if len(node.Args) > 0 {
		body = node.Args[0]
	}
	if body == nil {
		child := context
		values := lhs.MatchingNodes
		if !isRef {
			values = copyAll(values)
		}
		child.SetVariable(name, values)
		return child, nil
	}

	results := make([]*CandidateNode, 0)
	for _, value := range lhs.MatchingNodes {
		child := context
		bound := value
		if !isRef {
			bound = value.Copy()
		}
		child.SetVariable(name, []*CandidateNode{bound})
		out, err := d.GetMatchingNodes(child, body)
		if err != nil {
			return Context{}, err
		}
		results = append(results, out.MatchingNodes...)
	}
	return context.ChildContext(results), nil
}

func copyAll(nodes []*CandidateNode) []*CandidateNode {
	out := make([]*CandidateNode, len(nodes))
	for i, n := range nodes {
		out[i] = n.Copy()
	}
	return out
}

func reduceOperator(d *dataTreeNavigator, context Context, node *ExpressionNode) (Context, error) {
	asNode := node.Lhs
	name := asNode.Operation.StringValue
	lhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), asNode.Lhs)
	if err != nil {
		return Context{}, err
	}
	initCtx, err := d.GetMatchingNodes(context, node.Rhs)
	if err != nil {
		return Context{}, err
	}
	if len(initCtx.MatchingNodes) == 0 {
		return context.ChildContext(nil), nil
	}
	accumulator := initCtx.MatchingNodes[0].Copy()
	update := node.Args[0]

	for _, value := range lhs.MatchingNodes {
		child := context.SingleChildContext(accumulator)
		child.SetVariable(name, []*CandidateNode{value.Copy()})
		out, err := d.GetMatchingNodes(child, update)
		if err != nil {
			return Context{}, err
		}
		if len(out.MatchingNodes) == 0 {
			return context.ChildContext(nil), nil
		}
		accumulator = out.MatchingNodes[0]
	}
	return context.ChildContext([]*CandidateNode{accumulator}), nil
}

